CREATE FUNCTION "epm"."assignment_escalation_worker_cancel"("p_workspace" "text", "p_application" "text", "p_set" "text", "p_version" bigint, "p_assignment" "text", "p_due" timestamp with time zone, "p_generation" bigint, "p_claimant" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
 IF NOT pg_has_role(session_user,''epm_worker'',''member'') THEN RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_WORKER_REQUIRED'';END IF;
 PERFORM set_config(''epm.workspace_id'',p_workspace,true);
 PERFORM set_config(''epm.application_id'',p_application,true);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace||chr(31)||p_application,0));
 UPDATE epm.planning_assignment_due_occurrence SET status=''Cancelled'',claimant=NULL,lease_until=NULL
 WHERE workspace_id=p_workspace AND application_id=p_application
  AND assignment_set_id=p_set AND assignment_version=p_version
  AND assignment_id=p_assignment AND due_at=p_due AND status=''Running''
  AND claim_generation=p_generation AND claimant=p_claimant
  AND lease_until>=clock_timestamp();RETURN FOUND;
END';

CREATE FUNCTION "epm"."assignment_escalation_worker_renew"("p_workspace" "text", "p_application" "text", "p_set" "text", "p_version" bigint, "p_assignment" "text", "p_due" timestamp with time zone, "p_generation" bigint, "p_claimant" "text", "p_lease_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
 IF NOT pg_has_role(session_user,''epm_worker'',''member'') OR p_lease_seconds<5 OR p_lease_seconds>300 THEN
  RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_WORKER_ARGUMENT_INVALID'';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace||chr(31)||p_application,0));
 UPDATE epm.planning_assignment_due_occurrence SET
  lease_until=clock_timestamp()+p_lease_seconds*interval ''1 second''
 WHERE workspace_id=p_workspace AND application_id=p_application
  AND assignment_set_id=p_set AND assignment_version=p_version
  AND assignment_id=p_assignment AND due_at=p_due AND status=''Running''
  AND claim_generation=p_generation AND claimant=p_claimant
  AND lease_until>=clock_timestamp();
 RETURN FOUND;
END';

CREATE FUNCTION "epm"."assignment_escalation_worker_settle"("p_workspace" "text", "p_application" "text", "p_set" "text", "p_version" bigint, "p_assignment" "text", "p_due" timestamp with time zone, "p_generation" bigint, "p_claimant" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE o record;v record;s record;a jsonb;r jsonb;reviewer jsonb;ordinal bigint;
 control_version bigint;revision bigint;data_revision bigint;operation text;command_digest text;result jsonb;
BEGIN
 IF NOT pg_has_role(session_user,''epm_worker'',''member'') THEN RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_WORKER_REQUIRED'';END IF;
 PERFORM set_config(''epm.workspace_id'',p_workspace,true);
 PERFORM set_config(''epm.application_id'',p_application,true);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace||chr(31)||p_application,0));
 SELECT * INTO o FROM epm.planning_assignment_due_occurrence WHERE workspace_id=p_workspace
  AND application_id=p_application AND assignment_set_id=p_set AND assignment_version=p_version
  AND assignment_id=p_assignment AND due_at=p_due FOR UPDATE;
 IF o.status<>''Running'' OR o.claim_generation<>p_generation OR o.claimant<>p_claimant
    OR o.lease_until<clock_timestamp() THEN RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_CLAIM_STALE'';END IF;
 SELECT av.*,aps.active_assignment_set_id,aps.active_version INTO v
 FROM epm.planning_assignment_version av JOIN epm.planning_assignment_state aps
  ON aps.workspace_id=av.workspace_id AND aps.application_id=av.application_id
 WHERE av.workspace_id=p_workspace AND av.application_id=p_application
  AND av.assignment_set_id=p_set AND av.version=p_version;
 IF v.active_assignment_set_id IS DISTINCT FROM p_set OR v.active_version IS DISTINCT FROM p_version THEN
  RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_ASSIGNMENT_REVOKED'';END IF;
 IF NOT EXISTS(SELECT 1 FROM epm.planning_workflow_policy_state ps
  JOIN epm.planning_workflow_policy_version pv ON pv.workspace_id=ps.workspace_id
   AND pv.application_id=ps.application_id AND pv.policy_id=ps.active_policy_id
   AND pv.version=ps.active_version
  WHERE ps.workspace_id=p_workspace AND ps.application_id=p_application
   AND ps.active_policy_id=v.policy_id AND ps.active_version=v.policy_version
   AND pv.canonical_digest=v.policy_digest) THEN RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_POLICY_REVOKED'';END IF;
 SELECT value INTO a FROM jsonb_array_elements(v.definition->''assignments'') WHERE value->>''assignmentId''=p_assignment;
 IF a IS NULL THEN RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_ITEM_REVOKED'';END IF;
 reviewer:=a->''reviewerChain''->((a->''escalation''->>''reviewerOrdinal'')::integer-1);
 IF reviewer IS NULL THEN RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_REVIEWER_INVALID'';END IF;
 IF reviewer->>''kind''=''Subject'' AND NOT EXISTS(SELECT 1 FROM epm.application_access_grant g
   WHERE g.issuer=v.creator_issuer AND g.subject_id=reviewer->>''id''
    AND g.workspace_id=p_workspace AND g.application_id=p_application) THEN
   RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_REVIEWER_GRANT_REVOKED'';END IF;
 SELECT coalesce(max(event_ordinal),0)+1 INTO ordinal FROM epm.planning_assignment_control_event
  WHERE workspace_id=p_workspace AND application_id=p_application AND assignment_set_id=p_set
   AND assignment_version=p_version AND assignment_id=p_assignment;
 operation:=''assignment-escalation:''||p_set||'':''||p_version||'':''||p_assignment||'':''||extract(epoch from p_due)::bigint;
 command_digest:=encode(pg_catalog.sha256(convert_to(operation,''UTF8'')),''hex'');
 INSERT INTO epm.planning_assignment_control_event(workspace_id,application_id,
  assignment_set_id,assignment_version,assignment_id,event_ordinal,event_kind,
  actor_issuer,actor_subject_id,target_issuer,target_subject_id,target_group_id,
  reason,request_key,command_digest)
 VALUES(p_workspace,p_application,p_set,p_version,p_assignment,ordinal,''Escalated'',
  ''urn:openepm:worker'',p_claimant,CASE WHEN reviewer->>''kind''=''Subject'' THEN v.creator_issuer END,
  CASE WHEN reviewer->>''kind''=''Subject'' THEN reviewer->>''id'' END,
  CASE WHEN reviewer->>''kind''=''Group'' THEN reviewer->>''id'' END,
  ''Server due escalation'',operation,command_digest);
 SELECT coalesce(c.control_version,0)+1 INTO control_version
  FROM (SELECT 1) x LEFT JOIN epm.planning_assignment_control_current c
   ON c.workspace_id=p_workspace AND c.application_id=p_application
   AND c.assignment_set_id=p_set AND c.assignment_version=p_version AND c.assignment_id=p_assignment;
 INSERT INTO epm.planning_assignment_control_current(workspace_id,application_id,
  assignment_set_id,assignment_version,assignment_id,control_version,assignee_issuer,
  assignee_subject_id,assignee_group_id,delegation_depth,escalated_reviewer_ordinal)
 VALUES(p_workspace,p_application,p_set,p_version,p_assignment,control_version,
  CASE WHEN reviewer->>''kind''=''Subject'' THEN v.creator_issuer END,
  CASE WHEN reviewer->>''kind''=''Subject'' THEN reviewer->>''id'' END,
  CASE WHEN reviewer->>''kind''=''Group'' THEN reviewer->>''id'' END,0,
  (a->''escalation''->>''reviewerOrdinal'')::integer)
 ON CONFLICT(workspace_id,application_id,assignment_set_id,assignment_version,assignment_id)
 DO UPDATE SET control_version=excluded.control_version,assignee_issuer=excluded.assignee_issuer,
  assignee_subject_id=excluded.assignee_subject_id,assignee_group_id=excluded.assignee_group_id,
  delegator_issuer=NULL,delegator_subject_id=NULL,delegation_depth=0,
  delegation_expires_at=NULL,escalated_reviewer_ordinal=excluded.escalated_reviewer_ordinal,
  updated_at=transaction_timestamp();
 SELECT st.commit_revision+1,st.data_revision INTO revision,data_revision
  FROM epm.application_state st WHERE st.workspace_id=p_workspace
  AND st.application_id=p_application FOR UPDATE;
 UPDATE epm.application_state SET policy_revision=policy_revision+1,commit_revision=revision
  WHERE workspace_id=p_workspace AND application_id=p_application;
 result:=jsonb_build_object(''operationId'',operation,''assignmentId'',p_assignment,
  ''event'',''Escalated'',''eventOrdinal'',ordinal,''controlVersion'',control_version,
  ''dataRevision'',data_revision,''committedRevision'',revision);
 INSERT INTO epm.operation_receipt(workspace_id,application_id,operation_id,
  command_digest,actor_id,committed_revision,result)
 VALUES(p_workspace,p_application,operation,command_digest,p_claimant,revision,result)
 ON CONFLICT(workspace_id,application_id,operation_id) DO NOTHING;
 UPDATE epm.planning_assignment_due_occurrence SET status=''Completed'',claimant=NULL,
  lease_until=NULL,result_event_ordinal=ordinal,completed_at=transaction_timestamp()
 WHERE workspace_id=p_workspace AND application_id=p_application
  AND assignment_set_id=p_set AND assignment_version=p_version
  AND assignment_id=p_assignment AND due_at=p_due AND claim_generation=p_generation
  AND claimant=p_claimant AND lease_until>=clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION ''ASSIGNMENT_ESCALATION_CLAIM_STALE'';END IF;
 RETURN result;
END';

CREATE FUNCTION "epm"."coordinate_layout_dimension_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E' DECLARE w text;a text;BEGIN
 w:=CASE WHEN TG_OP=''DELETE'' THEN OLD.workspace_id ELSE NEW.workspace_id END;
 a:=CASE WHEN TG_OP=''DELETE'' THEN OLD.application_id ELSE NEW.application_id END;
 IF EXISTS(SELECT 1 FROM epm.layout_replacement_activation x WHERE x.workspace_id=w AND x.application_id=a
  AND x.status=''Activating'' AND epm.layout_replacement_activation_allowed(w,a,x.target_projection_generation)) THEN RETURN NULL;END IF;
 IF NOT pg_has_role(current_user,(SELECT relowner FROM pg_class WHERE oid=''epm.coordinate_layout''::regclass),''USAGE'')
  AND (current_setting(''epm.workspace_id'',true) IS DISTINCT FROM w OR current_setting(''epm.application_id'',true) IS DISTINCT FROM a)
 THEN RAISE EXCEPTION ''COORDINATE_LAYOUT_SCOPE_INVALID'';END IF;
 PERFORM epm.coordinate_layout_refresh(w,a);RETURN NULL;END ';

CREATE FUNCTION "epm"."coordinate_layout_refresh"("w" "text", "a" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE epoch bigint; dims text[]; roles jsonb; customs text[]; prior epm.coordinate_layout%ROWTYPE;
BEGIN
    SELECT schema_epoch INTO epoch FROM epm.application_state WHERE workspace_id=w AND application_id=a FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION ''APPLICATION_LAYOUT_UNAVAILABLE'' USING ERRCODE=''23514''; END IF;
    IF EXISTS(SELECT 1 FROM epm.dimension WHERE workspace_id=w AND application_id=a AND status=''Active''
        AND model_role IS NOT NULL AND model_role NOT IN (''Custom'',''Currency'') GROUP BY model_role HAVING count(*)>1) THEN
        RAISE EXCEPTION ''COORDINATE_LAYOUT_ROLE_AMBIGUOUS'' USING ERRCODE=''23514'';
    END IF;
    SELECT coalesce(array_agg(dimension_id ORDER BY dimension_id COLLATE "C"),''{}''::text[]),
        coalesce(jsonb_object_agg(model_role,dimension_id) FILTER(WHERE model_role IS NOT NULL AND model_role<>''Custom''),''{}''::jsonb),
        coalesce(array_agg(dimension_id ORDER BY dimension_id COLLATE "C") FILTER(WHERE model_role IS NULL OR model_role=''Custom''),''{}''::text[])
    INTO dims,roles,customs FROM epm.dimension WHERE workspace_id=w AND application_id=a AND status=''Active''
        AND model_role IS DISTINCT FROM ''Currency'';
    SELECT * INTO prior FROM epm.coordinate_layout WHERE workspace_id=w AND application_id=a AND schema_epoch=epoch;
    IF FOUND THEN
        IF ROW(prior.dimensions,prior.role_dimensions,prior.custom_dimensions) IS NOT DISTINCT FROM ROW(dims,roles,customs) THEN RETURN; END IF;
        IF EXISTS(SELECT 1 FROM epm.coordinate WHERE workspace_id=w AND application_id=a) THEN
            RAISE EXCEPTION ''POPULATED_AXIS_REBUILD_REQUIRED'' USING ERRCODE=''23514'';
        END IF;
        epoch=epoch+1;
        UPDATE epm.application_state SET schema_epoch=epoch WHERE workspace_id=w AND application_id=a;
    END IF;
    INSERT INTO epm.coordinate_layout(workspace_id,application_id,schema_epoch,dimensions,role_dimensions,custom_dimensions)
        VALUES(w,a,epoch,dims,roles,customs);
END ';

CREATE FUNCTION "epm"."cube_aggregate_worker_recover"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer:=0; step integer:=0;
BEGIN
  UPDATE epm.cube_aggregate_query SET status=''failed'',
    error_code=''CUBE_AGGREGATE_REQUEST_EXPIRED'',updated_at=transaction_timestamp()
  WHERE status=''ready'' AND expires_at<=clock_timestamp();
  GET DIAGNOSTICS step=ROW_COUNT; changed:=changed+step;

  UPDATE epm.cube_aggregate_query SET
    status=CASE WHEN status=''cancel_requested'' THEN ''cancelled''
                WHEN attempts<3 AND expires_at>clock_timestamp() THEN ''ready''
                ELSE ''failed'' END,
    error_code=CASE WHEN status=''cancel_requested'' THEN NULL
                    WHEN expires_at<=clock_timestamp() THEN ''CUBE_AGGREGATE_REQUEST_EXPIRED''
                    WHEN attempts>=3 THEN ''CUBE_AGGREGATE_RETRY_LIMIT'' ELSE NULL END,
    claim_generation=claim_generation+1,claimant=NULL,lease_until=NULL,
    updated_at=transaction_timestamp()
  WHERE status IN (''running'',''cancel_requested'') AND lease_until<=clock_timestamp();
  GET DIAGNOSTICS step=ROW_COUNT; changed:=changed+step;
  RETURN changed;
END ';

CREATE FUNCTION "epm"."cube_aggregate_worker_settle"("p_workspace" "text", "p_application" "text", "p_query" "text", "p_generation" bigint, "p_claimant" "text", "p_error" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
  IF p_error NOT IN (''CUBE_AGGREGATE_AUTHORIZATION_REVOKED'',
                     ''CUBE_AGGREGATE_COMPUTE_FAILED'') THEN
    RAISE EXCEPTION ''CUBE_AGGREGATE_WORKER_SETTLEMENT_INVALID'' USING ERRCODE=''22023'';
  END IF;
  UPDATE epm.cube_aggregate_query SET status=''failed'',error_code=p_error,
    claimant=NULL,lease_until=NULL,updated_at=transaction_timestamp()
  WHERE workspace_id=p_workspace AND application_id=p_application AND query_id=p_query
    AND status IN (''running'',''cancel_requested'') AND claim_generation=p_generation
    AND claimant=p_claimant AND lease_until>clock_timestamp();
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END ';

CREATE FUNCTION "epm"."delete_workspace_reset_owner_only"("p_workspace_id" "text", "p_operation_id" "text", "p_manifest_digest" "text", "p_schema_fingerprint" "text", "p_actor_digest" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE
    v_prior epm.workspace_reset_receipt%ROWTYPE;
    v_status text;
    v_table text;
    v_physical text;
    v_deleted bigint;
    v_counts jsonb := ''{}''::jsonb;
    v_apps jsonb;
    v_result jsonb;
BEGIN
    IF p_workspace_id IS NULL OR p_workspace_id = '''' OR
       p_workspace_id <> current_setting(''epm.workspace_id'',true) OR
       p_operation_id IS NULL OR
       p_operation_id !~ ''^[A-Za-z0-9._-]{8,128}$'' OR
       p_manifest_digest IS NULL OR
       p_manifest_digest !~ ''^[0-9a-f]{64}$'' OR
       p_schema_fingerprint IS NULL OR
       p_schema_fingerprint <> ''30a2efa926fe95d9d21d178d712a77ab8bb987f8ec9b334442aa3ae0981eb1aa'' OR
       p_actor_digest IS NULL OR
       p_actor_digest !~ ''^[0-9a-f]{64}$'' THEN
        RAISE EXCEPTION ''RESET_DELETE_ARGUMENTS_INVALID'';
    END IF;
    IF current_setting(''transaction_isolation'') <> ''read committed'' THEN
        RAISE EXCEPTION ''RESET_REQUIRES_READ_COMMITTED'';
    END IF;
    PERFORM pg_advisory_xact_lock(
        hashtextextended(''epm.security.workspace:'' || p_workspace_id,0));
    SELECT * INTO v_prior FROM epm.workspace_reset_receipt
        WHERE target_workspace_id=p_workspace_id
        AND operation_id=p_operation_id;
    IF FOUND THEN
        IF v_prior.manifest_digest<>p_manifest_digest OR
           v_prior.schema_fingerprint<>p_schema_fingerprint OR
           v_prior.actor_digest<>p_actor_digest THEN
            RAISE EXCEPTION ''IDEMPOTENCY_KEY_REUSED'';
        END IF;
        RETURN v_prior.result;
    END IF;
    SELECT status INTO v_status FROM epm.workspace
        WHERE workspace_id=p_workspace_id FOR UPDATE;
    IF v_status IS DISTINCT FROM ''Maintenance'' THEN
        RAISE EXCEPTION ''WORKSPACE_NOT_IN_MAINTENANCE'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.job WHERE workspace_id=p_workspace_id
        AND status IN (''accepted'',''ready'',''running'',''staged'',
                       ''cancel_requested'',''needs_inspection'')) THEN
        RAISE EXCEPTION ''UNSETTLED_OR_INSPECTION_JOBS'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.expression_rule_sequence
        WHERE workspace_id=p_workspace_id
          AND status IN (''accepted'',''running'',''cancel_requested'')) THEN
        RAISE EXCEPTION ''UNSETTLED_RULE_SEQUENCES'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.full_aggregate_sequence
        WHERE workspace_id=p_workspace_id
          AND status IN (''accepted'',''running'',''cancel_requested'')) THEN
        RAISE EXCEPTION ''UNSETTLED_FULL_SEQUENCES'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.source_import_execution
        WHERE workspace_id=p_workspace_id
          AND status IN (''Accepted'',''Claimed'',''Publishing'')) THEN
        RAISE EXCEPTION ''UNSETTLED_IMPORT_EXECUTIONS'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.source_batch
        WHERE workspace_id=p_workspace_id
        AND status IN (''staging'',''ready'')) THEN
        RAISE EXCEPTION ''UNPUBLISHED_SOURCE_BATCHES'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.job j
        JOIN epm.operation_receipt r
          ON r.workspace_id=j.workspace_id
         AND r.application_id=j.application_id
         AND r.operation_id=j.job_id
        WHERE j.workspace_id=p_workspace_id
        AND j.status<>''published'') THEN
        RAISE EXCEPTION ''JOB_RECEIPT_REQUIRES_INSPECTION'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.source_batch b
        JOIN epm.operation_receipt r
          ON r.workspace_id=b.workspace_id
         AND r.application_id=b.application_id
         AND r.operation_id=b.batch_id
        WHERE b.workspace_id=p_workspace_id
        AND b.status<>''published'') THEN
        RAISE EXCEPTION ''SOURCE_BATCH_RECEIPT_REQUIRES_INSPECTION'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.layout_replacement_request WHERE workspace_id=p_workspace_id AND status IN (''Accepted'',''Staging'',''Staged'')) THEN RAISE EXCEPTION ''UNSETTLED_LAYOUT_REPLACEMENT''; END IF;

    IF EXISTS (SELECT 1 FROM epm.layout_replacement_activation WHERE workspace_id=p_workspace_id AND status IN (''Requested'',''Activating'')) THEN RAISE EXCEPTION ''UNSETTLED_LAYOUT_ACTIVATION''; END IF;

    IF EXISTS(SELECT 1 FROM epm.fact_export_producer_request WHERE workspace_id=p_workspace_id AND status IN(''Accepted'',''Reading'',''Prepared'',''Publishing'')) THEN RAISE EXCEPTION ''UNSETTLED_EXPORT_PRODUCER'';END IF;
    IF EXISTS (SELECT 1 FROM epm.python_program_build WHERE workspace_id=p_workspace_id AND status IN (''accepted'',''ready'',''running'',''cancel_requested'')) THEN RAISE EXCEPTION ''UNSETTLED_PYTHON_BUILDS''; END IF;

    IF EXISTS (SELECT 1 FROM epm.cube_aggregate_query WHERE workspace_id=p_workspace_id AND status IN (''accepted'',''ready'',''running'',''computed'',''cancel_requested'')) THEN RAISE EXCEPTION ''UNSETTLED_CUBE_AGGREGATE_QUERIES''; END IF;

    IF EXISTS (SELECT 1 FROM epm.planning_forecast_occurrence WHERE workspace_id=p_workspace_id AND status IN (''accepted'',''ready'',''running'',''cancel_requested'',''business_published'',''needs_inspection'')) THEN RAISE EXCEPTION ''UNSETTLED_FORECAST_OCCURRENCES''; END IF;
    IF EXISTS (SELECT 1 FROM epm.planning_forecast_schedule_state WHERE workspace_id=p_workspace_id AND dispatch_claimant IS NOT NULL AND dispatch_lease_until IS NOT NULL) THEN RAISE EXCEPTION ''UNSETTLED_FORECAST_SCHEDULE_DISPATCH''; END IF;

    IF EXISTS (SELECT 1 FROM epm.python_program_workflow WHERE workspace_id=p_workspace_id AND status IN (''accepted'',''running'',''cancel_requested'',''needs_inspection'')) THEN RAISE EXCEPTION ''UNSETTLED_PYTHON_WORKFLOWS''; END IF;

    IF EXISTS (SELECT 1 FROM epm.transfer_cleanup_request WHERE workspace_id=p_workspace_id AND status IN (''Accepted'',''Running'')) THEN RAISE EXCEPTION ''UNSETTLED_TRANSFER_CLEANUP''; END IF;

    IF EXISTS (SELECT 1 FROM epm.planning_assignment_due_occurrence WHERE workspace_id=p_workspace_id AND status=''Running'' AND claimant IS NOT NULL AND lease_until IS NOT NULL) THEN RAISE EXCEPTION ''UNSETTLED_ASSIGNMENT_ESCALATION_CLAIMS''; END IF;

    IF EXISTS (SELECT 1 FROM epm.python_program_occurrence WHERE workspace_id=p_workspace_id AND status IN (''ready'',''running'',''building'',''running_program'',''cancel_requested'',''needs_inspection'')) OR EXISTS (SELECT 1 FROM epm.python_program_schedule_state WHERE workspace_id=p_workspace_id AND dispatch_claimant IS NOT NULL AND dispatch_lease_until>clock_timestamp()) THEN RAISE EXCEPTION ''UNSETTLED_PYTHON_SCHEDULE_WORK''; END IF;

    SELECT COALESCE(jsonb_agg(application_id ORDER BY application_id),
                    ''[]''::jsonb) INTO v_apps
        FROM epm.application WHERE workspace_id=p_workspace_id;

    \x2d- The order is pinned to the reviewed 0092 FK graph. All names are
    \x2d- constants; callers cannot supply a table or SQL fragment.
    \x2d- Self-referential journal FKs are removed by table-wide DELETE statements.
    PERFORM set_config(''epm.projection_cleanup_reset_context'',
        jsonb_build_array(p_workspace_id,pg_current_xact_id()::text,pg_backend_pid())::text,true);
    FOREACH v_table IN ARRAY ARRAY[
        ''planning_forecast_occurrence'',''planning_forecast_schedule_state'',
        ''planning_forecast_schedule_version'',''planning_forecast_progress'',
        ''python_program_occurrence'',''python_program_schedule_state'',''python_program_schedule_version'',''python_program_workflow_child'',''python_program_workflow'',
        ''python_plan_artifact'',''python_program_build'',
        ''python_program_publication'',''python_program_version'',
        ''python_environment_current'',''python_environment_version'',
        ''planning_forecast_definition_state'',''planning_forecast_definition_version'',
        ''cube_aggregate_result'',''cube_aggregate_query'',
        ''projection_cleanup_manifest'',
        ''projection_recovery_manifest'',
        ''coordinate_projection'',
        ''generic_fact_event'',''generic_fact_current'',
        ''rollup_placement_path_edge'',''rollup_source_lineage'',''rollup_placement_path'',''ownership_value_event'',
        ''ownership_value_current'',''allocation_basis_lineage'',''relationship'',
        ''planning_submission_event'',''manual_journal_line'',
        ''hierarchy_closure'',''hierarchy_active'',''expression_rule_publication'',''coordinate_member'',
        ''calendar_period_event'',''calendar_period_current'',
        ''ic_elimination_line'',''ic_elimination_publication'',
        ''cta_bridge_unit_effect'',''cta_bridge_source'',''cta_bridge'',''consolidation_layout_state'',''consolidation_layout_version'',''inventory_unrealized_schedule_state'',''inventory_unrealized_schedule_version'',''calculation_ratio_result'',''calculation_unit_result'',''calculation_result'',''calculation_publication'',
        ''text_fact_event'',''text_cell_current'',''planning_seed_lineage'',''source_import_execution'',''source_batch_row'',
        ''source_batch_chunk'',''semantic_column'',''policy_pack_draft'',
        ''acquisition_journal_line'',''acquisition_journal'',
        ''policy_activation_current'',''policy_activation_event'',
        ''policy_acquisition_approval'',''policy_acquisition_case_review'',
        ''policy_acquisition_case_bundle'',''policy_source_artifact'',
        ''financial_period_close_event'',''financial_period_close'',''planning_submission'',''planning_lock_event'',''planning_copy_origin'',
        ''numeric_fact_event'',''numeric_cell_current'',''member'',
        ''manual_journal'',''line_detail_event'',''line_detail_current'',
        ''job_event'',''job_dependency'',''hierarchy_version'',
        ''ic_elimination_withdrawal'',''ic_elimination_generation'',
        ''calculation_generation'',''source_batch'',''planning_slice_lock'',
        ''expression_rule_version'',''raw_operation_membership'',''execution_delegation_state'',''execution_delegation_version'',''fact_export_producer_page'',''fact_export_payload_chunk'',''fact_export_payload'',''fact_export_artifact'',''fact_export_producer_request'',''source_import_diagnostic_artifact'',''layout_replacement_activation_coordinate'',''layout_replacement_activation'',''layout_replacement_validation_certificate'',''layout_replacement_materialization_chunk'',''layout_replacement_private_detail'',''layout_replacement_private_text'',''layout_replacement_private_numeric'',''layout_replacement_private_coordinate'',''layout_replacement_materialization'',''layout_replacement_staged_coordinate'',''layout_replacement_generation'',''layout_replacement_request'',''planning_operation_policy_state'',''planning_operation_policy_version'',''planning_assigned_review_event'',''planning_assigned_reviewer'',''planning_assigned_submission'',''planning_assignment_control_current'',''planning_assignment_control_event'',''planning_assignment_due_occurrence'',''transfer_cleanup_certificate'',''transfer_cleanup_request'',''planning_assignment_state'',''planning_assignment_version'',''planning_workflow_policy_state'',''planning_workflow_policy_version'',''operation_receipt'',''job_event_cursor'',''job'',''generic_fact_table'',''expression_rule_sequence'',
        ''full_aggregate_sequence'',''coordinate'',''dimension'',
        ''coordinate_layout'',''rule_access_grant'',''application_state'',
        ''application_access_grant'',''workspace_lifecycle_receipt'',
        ''workspace_access_grant'',''security_operation_receipt'',
        ''application'',''worker_workspace_dispatch'',''workspace'']
    LOOP
        v_physical := CASE v_table WHEN ''numeric_cell_current'' THEN ''numeric_cell_projection'' WHEN ''text_cell_current'' THEN ''text_cell_projection'' WHEN ''line_detail_current'' THEN ''line_detail_projection'' WHEN ''generic_fact_current'' THEN ''generic_fact_projection'' WHEN ''coordinate_member'' THEN ''coordinate_member_projection'' WHEN ''coordinate_projection'' THEN ''coordinate_projection_state'' ELSE v_table END;
        EXECUTE format(''DELETE FROM epm.%I WHERE workspace_id=$1'',v_physical)
            USING p_workspace_id;
        GET DIAGNOSTICS v_deleted = ROW_COUNT;
        v_counts := v_counts || jsonb_build_object(v_table,v_deleted);
    END LOOP;

    PERFORM set_config(''epm.projection_cleanup_reset_context'','''',true);

    v_result := jsonb_build_object(
        ''workspaceId'',p_workspace_id,
        ''operationId'',p_operation_id,
        ''status'',''Deleted'',
        ''manifestDigest'',p_manifest_digest,
        ''schemaFingerprint'',p_schema_fingerprint,
        ''applicationIds'',v_apps,
        ''deletedCounts'',v_counts);
    INSERT INTO epm.workspace_reset_receipt
        (target_workspace_id,operation_id,manifest_digest,
         schema_fingerprint,actor_digest,result)
        VALUES (p_workspace_id,p_operation_id,p_manifest_digest,
                p_schema_fingerprint,p_actor_digest,v_result);
    INSERT INTO epm.security_audit
        (actor_id,action,workspace_id,target_digest,outcome,detail)
        VALUES (p_actor_digest,''workspace.reset.apply'',p_workspace_id,
                p_manifest_digest,''Accepted'',
                jsonb_build_object(''operationId'',p_operation_id,
                                   ''schemaFingerprint'',p_schema_fingerprint,
                                   ''applicationIds'',v_apps,
                                   ''deletedCounts'',v_counts));
    RETURN v_result;
END ';

CREATE FUNCTION "epm"."detail_items_match_total"("items" "jsonb", "expected" numeric) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE item jsonb;
DECLARE part numeric;
DECLARE total numeric := 0;
BEGIN
    IF jsonb_typeof(items) IS DISTINCT FROM ''array''
       OR jsonb_array_length(items) > 500 THEN
        RETURN false;
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
        IF jsonb_typeof(item) IS DISTINCT FROM ''object''
           OR jsonb_typeof(item->''description'') IS DISTINCT FROM ''string''
           OR length(item->>''description'') NOT BETWEEN 1 AND 80
           OR jsonb_typeof(item->''amount'') IS DISTINCT FROM ''string''
           OR (item->>''amount'') !~ ''^-?[0-9]+(\\.[0-9]{1,8})?$'' THEN
            RETURN false;
        END IF;
        part := (item->>''amount'')::numeric;
        IF part <= -100000000000000000000::numeric
           OR part >= 100000000000000000000::numeric THEN
            RETURN false;
        END IF;
        total := total + part;
    END LOOP;
    RETURN total = expected;
EXCEPTION WHEN others THEN
    RETURN false;
END ';

CREATE FUNCTION "epm"."export_payload_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
 IF TG_TABLE_NAME=''fact_export_payload_chunk'' THEN
  RAISE EXCEPTION ''EXPORT_PAYLOAD_CHUNK_IMMUTABLE'' USING ERRCODE=''23514'';
 END IF;
 IF (to_jsonb(NEW)-ARRAY[''status'',''finalized_at'',''retention_status'',
      ''retention_reason'',''retention_issuer'',''retention_subject_id'',
      ''retention_updated_at'']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY[''status'',''finalized_at'',''retention_status'',
      ''retention_reason'',''retention_issuer'',''retention_subject_id'',
      ''retention_updated_at'']) THEN
  RAISE EXCEPTION ''EXPORT_PAYLOAD_IMMUTABLE'' USING ERRCODE=''23514'';
 END IF;
 IF OLD.status=''complete'' AND NEW.status IS DISTINCT FROM OLD.status THEN
  RAISE EXCEPTION ''EXPORT_PAYLOAD_FINALIZED'' USING ERRCODE=''23514'';
 END IF;
 IF OLD.retention_status=''expired''
    AND NEW.retention_status IS DISTINCT FROM OLD.retention_status THEN
  RAISE EXCEPTION ''EXPORT_PAYLOAD_RETENTION_STALE'' USING ERRCODE=''23514'';
 END IF;
 RETURN NEW;
END ';

CREATE FUNCTION "epm"."export_producer_append"("w" "text", "a" "text", "rid" "text", "who" "text", "generation" bigint, "idx" integer, "request_cur" "text", "next_cur" "text", "digest" "text", "p" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'DECLARE prior epm.fact_export_producer_page%ROWTYPE;r epm.fact_export_producer_request%ROWTYPE;BEGIN
 SELECT * INTO r FROM epm.fact_export_producer_request WHERE workspace_id=w AND application_id=a AND request_id=rid FOR UPDATE;
 SELECT * INTO prior FROM epm.fact_export_producer_page WHERE workspace_id=w AND application_id=a AND request_id=rid AND page_index=idx;
 IF FOUND THEN IF prior.content_digest<>digest OR prior.page<>p OR prior.request_cursor IS DISTINCT FROM request_cur OR prior.next_cursor IS DISTINCT FROM next_cur THEN RAISE EXCEPTION ''EXPORT_PRODUCER_PAGE_CONFLICT'';END IF;RETURN true;END IF;
 IF r.status<>''Reading'' OR r.claimant<>who OR r.claim_generation<>generation OR r.lease_until<=clock_timestamp() THEN RAISE EXCEPTION ''EXPORT_PRODUCER_STALE_WORKER'';END IF;
 IF r.cancel_requested THEN RAISE EXCEPTION ''EXPORT_PRODUCER_CANCELLED'';END IF;
 IF idx<>r.next_page OR request_cur IS DISTINCT FROM r.expected_cursor THEN RAISE EXCEPTION ''EXPORT_PRODUCER_PAGE_GAP'';END IF;
 INSERT INTO epm.fact_export_producer_page VALUES(w,a,rid,idx,request_cur,CASE WHEN request_cur IS NULL THEN NULL ELSE encode(pg_catalog.sha256(convert_to(request_cur,''UTF8'')),''hex'') END,next_cur,CASE WHEN next_cur IS NULL THEN NULL ELSE encode(pg_catalog.sha256(convert_to(next_cur,''UTF8'')),''hex'') END,digest,p,transaction_timestamp());
 UPDATE epm.fact_export_producer_request SET next_page=next_page+1,expected_cursor=next_cur,lease_until=clock_timestamp()+interval ''120 seconds'',updated_at=transaction_timestamp() WHERE workspace_id=w AND application_id=a AND request_id=rid;RETURN true;END';

CREATE FUNCTION "epm"."export_producer_artifact_adopt"("w" "text", "a" "text", "rid" "text", "who" "text", "generation" bigint, "artifact" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE r epm.fact_export_producer_request%ROWTYPE;BEGIN
 SELECT * INTO r FROM epm.fact_export_producer_request WHERE workspace_id=w
  AND application_id=a AND request_id=rid FOR UPDATE;
 IF r.status<>''Publishing'' OR r.claimant<>who
  OR r.claim_generation<>generation OR r.lease_until<=clock_timestamp()
  OR r.cancel_requested THEN RAISE EXCEPTION ''EXPORT_PRODUCER_STALE_WORKER'';END IF;
 UPDATE epm.fact_export_artifact SET producer_claim_generation=generation
  WHERE workspace_id=w AND application_id=a AND artifact_id=artifact
   AND producer_request_id=rid;
 IF NOT FOUND THEN RAISE EXCEPTION ''EXPORT_PRODUCER_ARTIFACT_UNAVAILABLE'';END IF;
 RETURN true;
END';

CREATE FUNCTION "epm"."export_producer_complete"("w" "text", "a" "text", "rid" "text", "artifact" "text", "manifest_digest" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE r epm.fact_export_producer_request%ROWTYPE;BEGIN
 SELECT * INTO r FROM epm.fact_export_producer_request
  WHERE workspace_id=w AND application_id=a AND request_id=rid FOR UPDATE;
 IF r.status=''Completed'' AND r.artifact_id=artifact
  AND r.manifest->>''manifestDigest''=manifest_digest THEN RETURN true;END IF;
 RAISE EXCEPTION ''EXPORT_PRODUCER_PUBLISH_CLAIM_REQUIRED'';
END';

CREATE FUNCTION "epm"."export_producer_publish_claim"("w" "text", "a" "text", "rid" "text", "who" "text", "seconds" integer) RETURNS TABLE("claim_generation" bigint, "manifest_digest" "text", "status" "text", "artifact_id" "text", "payload_digest" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE r epm.fact_export_producer_request%ROWTYPE;
BEGIN
 IF seconds NOT BETWEEN 30 AND 300 OR length(who) NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION ''EXPORT_PRODUCER_PUBLISH_CLAIM_INVALID'';END IF;
 SELECT * INTO r FROM epm.fact_export_producer_request
  WHERE workspace_id=w AND application_id=a AND request_id=rid FOR UPDATE;
 IF r.status=''Completed'' THEN
  RETURN QUERY SELECT r.claim_generation,r.manifest->>''manifestDigest'',
   r.status,r.artifact_id,r.payload_digest;RETURN;
 END IF;
 IF r.cancel_requested OR r.status=''Cancelled'' THEN
  RAISE EXCEPTION ''EXPORT_PRODUCER_CANCELLED'';END IF;
 IF r.status=''Publishing'' AND r.claimant=who AND r.lease_until>clock_timestamp() THEN
  RETURN QUERY SELECT r.claim_generation,r.manifest->>''manifestDigest'',
   r.status,r.artifact_id,r.payload_digest;RETURN;
 END IF;
 IF r.status<>''Prepared'' AND NOT(r.status=''Publishing'' AND r.lease_until<=clock_timestamp()) THEN
  RAISE EXCEPTION ''EXPORT_PRODUCER_NOT_PREPARED'';END IF;
 UPDATE epm.fact_export_producer_request p SET status=''Publishing'',
  claim_generation=p.claim_generation+1,claimant=who,
  lease_until=clock_timestamp()+make_interval(secs=>seconds),
  updated_at=transaction_timestamp()
 WHERE p.workspace_id=w AND p.application_id=a AND p.request_id=rid
 RETURNING p.claim_generation,p.manifest->>''manifestDigest'',p.status,
  p.artifact_id,p.payload_digest INTO claim_generation,manifest_digest,status,
  artifact_id,payload_digest;
 RETURN NEXT;
END';

CREATE FUNCTION "epm"."fact_commit_epoch_close"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    PERFORM epm.fact_scope_check(NEW.workspace_id,NEW.application_id,true);
    UPDATE epm.application_state SET commit_open=false WHERE workspace_id=NEW.workspace_id
      AND application_id=NEW.application_id AND commit_open;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."fact_commit_epoch_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    IF TG_OP=''INSERT'' THEN NEW.commit_open=false; RETURN NEW; END IF;
    IF NEW.commit_revision<OLD.commit_revision THEN
        RAISE EXCEPTION ''FACT_COMMIT_REVISION_REGRESSION'' USING ERRCODE=''23514'';
    ELSIF NEW.commit_revision>OLD.commit_revision THEN NEW.commit_open=true;
    ELSIF NEW.commit_open AND NOT OLD.commit_open THEN
        RAISE EXCEPTION ''FACT_COMMIT_EPOCH_REOPENED'' USING ERRCODE=''23514'';
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."fact_projections_rebuild"("w" "text", "a" "text", "jid" "text", "claimant_name" "text", "generation" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE s epm.application_state%ROWTYPE; j epm.job%ROWTYPE; p jsonb;
    output jsonb; counts jsonb:=''{}''; affected bigint; revision bigint;
BEGIN
    \x2d- Check caller scope even under definer identity. The caller cannot create
    \x2d- a valid context by setting a GUC: invoker guards also require owner identity.
    IF current_setting(''epm.workspace_id'',true) IS DISTINCT FROM w
       OR current_setting(''epm.application_id'',true) IS DISTINCT FROM a THEN
        RAISE EXCEPTION ''RECONSTRUCTION_SCOPE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    PERFORM pg_advisory_xact_lock_shared(hashtextextended(''epm.security.workspace:''||w,0));
    SELECT * INTO s FROM epm.application_state WHERE workspace_id=w AND application_id=a FOR UPDATE;
    SELECT * INTO j FROM epm.job WHERE workspace_id=w AND application_id=a AND job_id=jid;
    IF s.application_id IS NULL OR j.job_id IS NULL OR j.function_name<>''facts.projections.rebuild''
       OR j.compiler_version<>''fact-projections-rebuild-v1''
       OR j.plan_digest<>''e8b2d3005d3d668c1bd65a419d96b049b6fcb35a81d1d26f649c16d4a5d9504c''
       OR j.resource_class<>''long'' THEN
        RAISE EXCEPTION ''RECONSTRUCTION_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF j.status<>''running'' OR j.claimant IS DISTINCT FROM claimant_name
       OR j.claim_generation IS DISTINCT FROM generation
       OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    p:=j.normalized_program;
    IF p->>''function'' IS DISTINCT FROM ''facts.projections.rebuild'' OR p->>''version'' IS DISTINCT FROM ''1''
       OR p-ARRAY[''version'',''function'',''reason'',''sourceCommitRevision'',''schemaEpoch'']<>''{}''::jsonb
       OR jsonb_typeof(p->''reason'') IS DISTINCT FROM ''string''
       OR length(p->>''reason'') NOT BETWEEN 1 AND 500 OR (p->>''reason'')~''^[[:space:]]|[[:space:]]$''
       OR jsonb_typeof(p->''sourceCommitRevision'') IS DISTINCT FROM ''number''
       OR jsonb_typeof(p->''schemaEpoch'') IS DISTINCT FROM ''number''
       OR (p->>''sourceCommitRevision'')!~''^(0|[1-9][0-9]*)$''
       OR (p->>''schemaEpoch'')!~''^(0|[1-9][0-9]*)$'' THEN
        RAISE EXCEPTION ''RECONSTRUCTION_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    \x2d- Canonical UTF-8 serialization matches the fixed Python compiler''s sorted
    \x2d- JSON keys. JSON string escaping stays native; never remove whitespace from
    \x2d- inside a reason or accept an arbitrary stored receipt digest.
    IF j.program_digest IS DISTINCT FROM encode(sha256(convert_to(
        ''{"function":"facts.projections.rebuild","reason":''||(p->''reason'')::text||
        '',"schemaEpoch":''||(p->>''schemaEpoch'')||'',"sourceCommitRevision":''||
        (p->>''sourceCommitRevision'')||'',"version":1}'', ''UTF8'')),''hex'') THEN
        RAISE EXCEPTION ''RECONSTRUCTION_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF s.commit_open OR s.commit_revision<>(p->>''sourceCommitRevision'')::bigint
       OR s.schema_epoch<>(p->>''schemaEpoch'')::bigint
       OR s.metadata_revision<>j.expected_metadata_revision OR s.data_revision<>j.expected_data_revision
       OR s.policy_revision<>j.expected_policy_revision THEN
        RAISE EXCEPTION ''STALE_RECONSTRUCTION_SOURCE'' USING ERRCODE=''23514'';
    END IF;
    IF s.processing_mode<>''Active''
       OR NOT EXISTS(SELECT 1 FROM epm.workspace WHERE workspace_id=w AND status=''Active'')
       OR NOT EXISTS(SELECT 1 FROM epm.application WHERE workspace_id=w AND application_id=a AND status=''Active'') THEN
        RAISE EXCEPTION ''APPLICATION_NOT_WRITABLE'' USING ERRCODE=''23514'';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM epm.workspace_access_grant WHERE workspace_id=w AND issuer=j.issuer
          AND subject_id=j.subject_id AND role=''Administrator'')
       AND NOT EXISTS(SELECT 1 FROM epm.application_access_grant WHERE workspace_id=w AND application_id=a
          AND issuer=j.issuer AND subject_id=j.subject_id AND role=''Administrator'') THEN
        RAISE EXCEPTION ''APPLICATION_GRANT_REQUIRED'' USING ERRCODE=''23514'';
    END IF;
    PERFORM epm.fact_reconstruction_validate(w,a,s.commit_revision);
    PERFORM set_config(''epm.fact_reconstruction_context'',
        jsonb_build_array(w,a,pg_current_xact_id()::text,pg_backend_pid())::text,true);

    \x2d- Membership is also derived. Missing or misassigned rows otherwise leave
    \x2d- indexed readers/calculations wrong even after amounts are reconstructed.
    INSERT INTO epm.coordinate_member_projection(projection_generation,workspace_id,application_id,coordinate_id,dimension_id,member_id)
    SELECT (SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a),w,a,c.coordinate_id,pair.key,pair.value FROM epm.coordinate c
    CROSS JOIN LATERAL jsonb_each_text(c.members) pair
    WHERE c.workspace_id=w AND c.application_id=a
    ON CONFLICT(workspace_id,application_id,projection_generation,coordinate_id,dimension_id) DO UPDATE SET member_id=excluded.member_id;
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''coordinateMemberRows'',affected);
    DELETE FROM epm.coordinate_member_projection m USING epm.coordinate c
    WHERE m.workspace_id=w AND m.application_id=a AND m.projection_generation=(SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a) AND c.workspace_id=w AND c.application_id=a
      AND m.coordinate_id=c.coordinate_id AND (c.members->>m.dimension_id) IS DISTINCT FROM m.member_id;
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''coordinateMemberRemoved'',affected);

    \x2d- Current tables are derived, not sources. Preserve original event IDs,
    \x2d- committed revisions and cleared numeric/text CAS tombstones.
    INSERT INTO epm.numeric_cell_projection(projection_generation,workspace_id,application_id,coordinate_id,present,amount,change_id,last_revision)
    SELECT DISTINCT ON(coordinate_id) (SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a),w,a,coordinate_id,present,resulting_amount,change_id,committed_revision
    FROM epm.numeric_fact_event WHERE workspace_id=w AND application_id=a
    ORDER BY coordinate_id,committed_revision DESC,line_ordinal DESC
    ON CONFLICT(workspace_id,application_id,projection_generation,coordinate_id) DO UPDATE SET
        present=excluded.present,amount=excluded.amount,change_id=excluded.change_id,last_revision=excluded.last_revision;
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''numericRows'',affected);
    DELETE FROM epm.numeric_cell_projection c WHERE c.workspace_id=w AND c.application_id=a AND c.projection_generation=(SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a)
      AND NOT EXISTS(SELECT 1 FROM epm.numeric_fact_event e WHERE e.workspace_id=w AND e.application_id=a
          AND e.coordinate_id=c.coordinate_id);
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''numericRemoved'',affected);

    INSERT INTO epm.text_cell_projection(projection_generation,workspace_id,application_id,coordinate_id,present,text_value,change_id,last_revision)
    SELECT DISTINCT ON(coordinate_id) (SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a),w,a,coordinate_id,present,resulting_value,change_id,committed_revision
    FROM epm.text_fact_event WHERE workspace_id=w AND application_id=a
    ORDER BY coordinate_id,committed_revision DESC,line_ordinal DESC
    ON CONFLICT(workspace_id,application_id,projection_generation,coordinate_id) DO UPDATE SET
        present=excluded.present,text_value=excluded.text_value,change_id=excluded.change_id,last_revision=excluded.last_revision;
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''textRows'',affected);
    DELETE FROM epm.text_cell_projection c WHERE c.workspace_id=w AND c.application_id=a AND c.projection_generation=(SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a)
      AND NOT EXISTS(SELECT 1 FROM epm.text_fact_event e WHERE e.workspace_id=w AND e.application_id=a
          AND e.coordinate_id=c.coordinate_id);
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''textRemoved'',affected);

    WITH latest AS(SELECT DISTINCT ON(coordinate_id) * FROM epm.line_detail_event
        WHERE workspace_id=w AND application_id=a ORDER BY coordinate_id,committed_revision DESC)
    INSERT INTO epm.line_detail_projection(projection_generation,workspace_id,application_id,coordinate_id,items,total,change_id,last_revision)
    SELECT (SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a),w,a,coordinate_id,items,total,change_id,committed_revision FROM latest WHERE present
    ON CONFLICT(workspace_id,application_id,projection_generation,coordinate_id) DO UPDATE SET
        items=excluded.items,total=excluded.total,change_id=excluded.change_id,last_revision=excluded.last_revision;
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''detailRows'',affected);
    DELETE FROM epm.line_detail_projection c WHERE c.workspace_id=w AND c.application_id=a AND c.projection_generation=(SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a)
      AND NOT EXISTS(SELECT 1 FROM (SELECT present FROM epm.line_detail_event e
          WHERE e.workspace_id=w AND e.application_id=a AND e.coordinate_id=c.coordinate_id
          ORDER BY committed_revision DESC LIMIT 1)latest WHERE present);
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''detailRemoved'',affected);

    WITH latest AS(SELECT DISTINCT ON(table_id,series_key) * FROM epm.generic_fact_event
        WHERE workspace_id=w AND application_id=a ORDER BY table_id,series_key,committed_revision DESC)
    INSERT INTO epm.generic_fact_projection(projection_generation,workspace_id,application_id,table_id,series_key,value,change_id,last_revision,updated_at)
    SELECT (SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a),w,a,table_id,series_key,after_value,resulting_change_id,committed_revision,created_at
    FROM latest WHERE action<>''Delete''
    ON CONFLICT(workspace_id,application_id,projection_generation,table_id,series_key) DO UPDATE SET
        value=excluded.value,change_id=excluded.change_id,last_revision=excluded.last_revision,updated_at=excluded.updated_at;
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''genericRows'',affected);
    DELETE FROM epm.generic_fact_projection c WHERE c.workspace_id=w AND c.application_id=a AND c.projection_generation=(SELECT active_projection_generation FROM epm.application_state WHERE workspace_id=w AND application_id=a)
      AND NOT EXISTS(SELECT 1 FROM (SELECT action FROM epm.generic_fact_event e
          WHERE e.workspace_id=w AND e.application_id=a AND e.table_id=c.table_id AND e.series_key=c.series_key
          ORDER BY committed_revision DESC LIMIT 1)latest WHERE action<>''Delete'');
    GET DIAGNOSTICS affected=ROW_COUNT; counts:=counts||jsonb_build_object(''genericRemoved'',affected);
    PERFORM epm.coordinate_projection_build(w,a);

    \x2d- Flush checks while owner/context is valid, then close the privilege window
    \x2d- before returning to fixed Python. No event/receipt seal is reopened.
    SET CONSTRAINTS epm.generic_projection_complete IMMEDIATE;
    SET CONSTRAINTS epm.generic_projection_complete DEFERRED;
    PERFORM set_config(''epm.fact_reconstruction_context'','''',true);

    \x2d- Cancellation, heartbeat and takeover may proceed until this final fence.
    SELECT * INTO j FROM epm.job WHERE workspace_id=w AND application_id=a AND job_id=jid FOR UPDATE;
    IF j.status<>''running'' OR j.claimant IS DISTINCT FROM claimant_name
       OR j.claim_generation IS DISTINCT FROM generation
       OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    revision:=s.commit_revision+1;
    output:=jsonb_build_object(''committedRevision'',revision,''sourceCommitRevision'',s.commit_revision,
        ''schemaEpoch'',s.schema_epoch,''reason'',p->>''reason'',''projections'',counts,''historyPreserved'',true);
    UPDATE epm.application_state SET commit_revision=revision WHERE workspace_id=w AND application_id=a;
    INSERT INTO epm.operation_receipt(workspace_id,application_id,operation_id,command_digest,actor_id,committed_revision,result)
        VALUES(w,a,jid,j.program_digest,j.subject_id,revision,output);
    UPDATE epm.job SET status=''published'',receipt_revision=revision,result=output,
        claimant=NULL,lease_until=NULL,updated_at=transaction_timestamp()
        WHERE workspace_id=w AND application_id=a AND job_id=jid;
    RETURN output;
END ';

CREATE FUNCTION "epm"."fact_projections_rebuild_step"("w" "text", "a" "text", "jid" "text", "claimant_name" "text", "generation" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE s epm.application_state%ROWTYPE; j epm.job%ROWTYPE;
    m epm.projection_recovery_manifest%ROWTYPE; layout epm.coordinate_layout%ROWTYPE;
    e record; previous jsonb; p jsonb; output jsonb; revision bigint; highwater bigint;
    processed integer:=0; bytes_used bigint:=0; event_bytes bigint; exhausted boolean:=true;
    next_phase text; counter_name text; numeric_present boolean; numeric_amount numeric;
BEGIN
    IF current_setting(''epm.workspace_id'',true) IS DISTINCT FROM w
       OR current_setting(''epm.application_id'',true) IS DISTINCT FROM a THEN
        RAISE EXCEPTION ''RECONSTRUCTION_SCOPE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    PERFORM pg_advisory_xact_lock_shared(hashtextextended(''epm.security.workspace:''||w,0));
    SELECT * INTO s FROM epm.application_state WHERE workspace_id=w AND application_id=a FOR UPDATE;
    SELECT * INTO j FROM epm.job WHERE workspace_id=w AND application_id=a AND job_id=jid;
    IF s.application_id IS NULL OR j.job_id IS NULL OR j.function_name<>''facts.projections.rebuild''
       OR j.compiler_version<>''fact-projections-rebuild-v2''
       OR j.plan_digest<>''bdb24ea0001349b4f4b2778486cfcf01856ede90cf8a0b297807e56162c4aea8''
       OR j.resource_class<>''long'' THEN
        RAISE EXCEPTION ''RECONSTRUCTION_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF j.status<>''running'' OR j.claimant IS DISTINCT FROM claimant_name
       OR j.claim_generation IS DISTINCT FROM generation
       OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    p:=j.normalized_program;
    IF p->>''function'' IS DISTINCT FROM ''facts.projections.rebuild'' OR p->''version'' IS DISTINCT FROM ''2''::jsonb
       OR p-ARRAY[''version'',''function'',''reason'',''sourceCommitRevision'',''schemaEpoch'']<>''{}''::jsonb
       OR jsonb_typeof(p->''reason'') IS DISTINCT FROM ''string''
       OR length(p->>''reason'') NOT BETWEEN 1 AND 500 OR (p->>''reason'')~''^[[:space:]]|[[:space:]]$''
       OR jsonb_typeof(p->''sourceCommitRevision'') IS DISTINCT FROM ''number''
       OR jsonb_typeof(p->''schemaEpoch'') IS DISTINCT FROM ''number''
       OR (p->>''sourceCommitRevision'')!~''^(0|[1-9][0-9]*)$''
       OR (p->>''schemaEpoch'')!~''^(0|[1-9][0-9]*)$'' THEN
        RAISE EXCEPTION ''RECONSTRUCTION_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF j.program_digest IS DISTINCT FROM encode(sha256(convert_to(
        ''{"function":"facts.projections.rebuild","reason":''||(p->''reason'')::text||
        '',"schemaEpoch":''||(p->>''schemaEpoch'')||'',"sourceCommitRevision":''||
        (p->>''sourceCommitRevision'')||'',"version":2}'', ''UTF8'')),''hex'') THEN
        RAISE EXCEPTION ''RECONSTRUCTION_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF s.commit_open OR s.commit_revision<>(p->>''sourceCommitRevision'')::bigint
       OR s.schema_epoch<>(p->>''schemaEpoch'')::bigint
       OR s.metadata_revision<>j.expected_metadata_revision OR s.data_revision<>j.expected_data_revision
       OR s.policy_revision<>j.expected_policy_revision THEN
        RAISE EXCEPTION ''STALE_RECONSTRUCTION_SOURCE'' USING ERRCODE=''23514'';
    END IF;
    IF s.processing_mode<>''Active''
       OR NOT EXISTS(SELECT 1 FROM epm.workspace WHERE workspace_id=w AND status=''Active'')
       OR NOT EXISTS(SELECT 1 FROM epm.application WHERE workspace_id=w AND application_id=a AND status=''Active'') THEN
        RAISE EXCEPTION ''APPLICATION_NOT_WRITABLE'' USING ERRCODE=''23514'';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM epm.workspace_access_grant WHERE workspace_id=w AND issuer=j.issuer
          AND subject_id=j.subject_id AND role=''Administrator'')
       AND NOT EXISTS(SELECT 1 FROM epm.application_access_grant WHERE workspace_id=w AND application_id=a
          AND issuer=j.issuer AND subject_id=j.subject_id AND role=''Administrator'') THEN
        RAISE EXCEPTION ''APPLICATION_GRANT_REQUIRED'' USING ERRCODE=''23514'';
    END IF;
    SELECT coalesce((SELECT coordinate_id FROM epm.coordinate WHERE workspace_id=w AND application_id=a
        ORDER BY coordinate_id DESC LIMIT 1),0) INTO highwater;
    SELECT * INTO m FROM epm.projection_recovery_manifest
        WHERE workspace_id=w AND application_id=a AND job_id=jid FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO epm.projection_recovery_manifest(workspace_id,application_id,job_id,target_generation,
            original_generation,source_commit_revision,schema_epoch,metadata_revision,data_revision,policy_revision,
            coordinate_highwater,phase)
        VALUES(w,a,jid,greatest(s.active_projection_generation,coalesce((SELECT target_generation
            FROM epm.projection_recovery_manifest WHERE workspace_id=w AND application_id=a
            ORDER BY target_generation DESC LIMIT 1),0))+1,s.active_projection_generation,s.commit_revision,
            s.schema_epoch,s.metadata_revision,s.data_revision,s.policy_revision,highwater,''coordinates'')
        RETURNING * INTO m;
        IF EXISTS(SELECT 1 FROM epm.numeric_cell_projection WHERE workspace_id=w AND application_id=a AND projection_generation=m.target_generation)
            OR EXISTS(SELECT 1 FROM epm.text_cell_projection WHERE workspace_id=w AND application_id=a AND projection_generation=m.target_generation)
            OR EXISTS(SELECT 1 FROM epm.line_detail_projection WHERE workspace_id=w AND application_id=a AND projection_generation=m.target_generation)
            OR EXISTS(SELECT 1 FROM epm.generic_fact_projection WHERE workspace_id=w AND application_id=a AND projection_generation=m.target_generation)
            OR EXISTS(SELECT 1 FROM epm.coordinate_member_projection WHERE workspace_id=w AND application_id=a AND projection_generation=m.target_generation)
            OR EXISTS(SELECT 1 FROM epm.coordinate_projection_state WHERE workspace_id=w AND application_id=a AND projection_generation=m.target_generation) THEN
            RAISE EXCEPTION ''RECONSTRUCTION_TARGET_NOT_EMPTY'' USING ERRCODE=''23514'';
        END IF;
    END IF;
    IF ROW(m.original_generation,m.source_commit_revision,m.schema_epoch,m.metadata_revision,m.data_revision,
        m.policy_revision,m.coordinate_highwater) IS DISTINCT FROM ROW(s.active_projection_generation,
        s.commit_revision,s.schema_epoch,s.metadata_revision,s.data_revision,s.policy_revision,highwater) THEN
        RAISE EXCEPTION ''STALE_RECONSTRUCTION_SOURCE'' USING ERRCODE=''23514'';
    END IF;
    UPDATE epm.projection_recovery_manifest SET context_xid=pg_current_xact_id()::text,
        context_pid=pg_backend_pid(),context_claim=generation WHERE workspace_id=w AND application_id=a AND job_id=jid;
    PERFORM set_config(''epm.staged_projection_context'',jsonb_build_array(w,a,jid,m.target_generation,
        generation,pg_current_xact_id()::text,pg_backend_pid())::text,true);
    \x2d- Existing statement guards still compare canonical latest events exactly.
    \x2d- Inactive row writes additionally require the target/phase-bound capability.
    PERFORM set_config(''epm.fact_reconstruction_context'',
        jsonb_build_array(w,a,pg_current_xact_id()::text,pg_backend_pid())::text,true);

    IF m.phase=''coordinates'' THEN
        SELECT * INTO layout FROM epm.coordinate_layout WHERE workspace_id=w AND application_id=a AND schema_epoch=m.schema_epoch;
        IF layout.schema_epoch IS NULL AND highwater>0 THEN
            RAISE EXCEPTION ''RECONSTRUCTION_LAYOUT_INVALID'' USING ERRCODE=''23514'';
        END IF;
        FOR e IN SELECT * FROM epm.coordinate WHERE workspace_id=w AND application_id=a
            AND coordinate_id>m.coordinate_cursor AND coordinate_id<=m.coordinate_highwater
            ORDER BY coordinate_id LIMIT 128 LOOP
            event_bytes:=octet_length(to_jsonb(e)::text);
            IF processed>0 AND bytes_used+event_bytes>1048576 THEN exhausted:=false; EXIT; END IF;
            IF ARRAY(SELECT key FROM jsonb_object_keys(e.members) keys(key) ORDER BY key COLLATE "C")
                IS DISTINCT FROM layout.dimensions THEN
                RAISE EXCEPTION ''COORDINATE_LAYOUT_GRAIN_MISMATCH'' USING ERRCODE=''23514'';
            END IF;
            INSERT INTO epm.coordinate_member_projection(workspace_id,application_id,projection_generation,coordinate_id,dimension_id,member_id)
                SELECT w,a,m.target_generation,e.coordinate_id,key,value FROM jsonb_each_text(e.members);
            INSERT INTO epm.coordinate_projection_state(workspace_id,application_id,projection_generation,coordinate_id,schema_epoch,
                entity_member,account_member,scenario_member,year_member,period_member,value_member,view_member,icp_member,data_type_member,custom_members)
            VALUES(w,a,m.target_generation,e.coordinate_id,m.schema_epoch,
                e.members->>(layout.role_dimensions->>''Entity''),e.members->>(layout.role_dimensions->>''Account''),
                e.members->>(layout.role_dimensions->>''Scenario''),e.members->>(layout.role_dimensions->>''Year''),
                e.members->>(layout.role_dimensions->>''Period''),e.members->>(layout.role_dimensions->>''Value''),
                e.members->>(layout.role_dimensions->>''View''),e.members->>(layout.role_dimensions->>''ICP''),
                e.members->>(layout.role_dimensions->>''DataType''),
                ARRAY(SELECT e.members->>axis FROM unnest(layout.custom_dimensions) WITH ORDINALITY axes(axis,position) ORDER BY position));
            m.coordinate_cursor:=e.coordinate_id; processed:=processed+1; bytes_used:=bytes_used+event_bytes;
        END LOOP;
        counter_name:=''coordinateRows''; next_phase:=''numeric'';
    ELSIF m.phase=''numeric'' THEN
        FOR e IN SELECT * FROM epm.numeric_fact_event WHERE workspace_id=w AND application_id=a
            AND ROW(coordinate_id,committed_revision,line_ordinal)>ROW(m.coordinate_cursor,m.revision_cursor,m.ordinal_cursor)
            ORDER BY coordinate_id,committed_revision,line_ordinal LIMIT 128 LOOP
            event_bytes:=octet_length(to_jsonb(e)::text);
            IF processed>0 AND bytes_used+event_bytes>1048576 THEN exhausted:=false; EXIT; END IF;
            previous:=m.carry;
            PERFORM epm.projection_recovery_receipt(w,a,e.operation_id,e.committed_revision,m.source_commit_revision);
            IF e.present IS DISTINCT FROM (e.kind<>''clear'') OR e.delta IS DISTINCT FROM
                coalesce(e.resulting_amount,0)-coalesce((previous->>''resulting_amount'')::numeric,0) THEN
                RAISE EXCEPTION ''RECONSTRUCTION_NUMERIC_LINEAGE_INVALID'' USING ERRCODE=''23514'';
            END IF;
            m.carry:=to_jsonb(e);
            IF NOT EXISTS(SELECT 1 FROM epm.numeric_fact_event WHERE workspace_id=w AND application_id=a
                AND coordinate_id=e.coordinate_id AND ROW(committed_revision,line_ordinal)>ROW(e.committed_revision,e.line_ordinal)) THEN
                INSERT INTO epm.numeric_cell_projection(workspace_id,application_id,projection_generation,coordinate_id,present,amount,change_id,last_revision)
                    VALUES(w,a,m.target_generation,e.coordinate_id,e.present,e.resulting_amount,e.change_id,e.committed_revision);
                m.carry:=NULL;
                m.counters:=m.counters||jsonb_build_object(''numericRows'',coalesce((m.counters->>''numericRows'')::bigint,0)+1);
            END IF;
            m.coordinate_cursor:=e.coordinate_id; m.revision_cursor:=e.committed_revision; m.ordinal_cursor:=e.line_ordinal;
            processed:=processed+1; bytes_used:=bytes_used+event_bytes;
        END LOOP;
        counter_name:=''numericEvents''; next_phase:=''text'';
    ELSIF m.phase=''text'' THEN
        FOR e IN SELECT * FROM epm.text_fact_event WHERE workspace_id=w AND application_id=a
            AND ROW(coordinate_id,committed_revision,line_ordinal)>ROW(m.coordinate_cursor,m.revision_cursor,m.ordinal_cursor)
            ORDER BY coordinate_id,committed_revision,line_ordinal LIMIT 128 LOOP
            event_bytes:=octet_length(to_jsonb(e)::text);
            IF processed>0 AND bytes_used+event_bytes>1048576 THEN exhausted:=false; EXIT; END IF;
            previous:=m.carry;
            PERFORM epm.projection_recovery_receipt(w,a,e.operation_id,e.committed_revision,m.source_commit_revision);
            IF e.present IS DISTINCT FROM (e.kind<>''clear'')
                OR e.prior_present IS DISTINCT FROM coalesce((previous->>''present'')::boolean,false)
                OR e.prior_value IS DISTINCT FROM previous->>''resulting_value'' THEN
                RAISE EXCEPTION ''RECONSTRUCTION_TEXT_LINEAGE_INVALID'' USING ERRCODE=''23514'';
            END IF;
            m.carry:=to_jsonb(e);
            IF NOT EXISTS(SELECT 1 FROM epm.text_fact_event WHERE workspace_id=w AND application_id=a
                AND coordinate_id=e.coordinate_id AND ROW(committed_revision,line_ordinal)>ROW(e.committed_revision,e.line_ordinal)) THEN
                IF e.present AND EXISTS(SELECT 1 FROM epm.numeric_cell_projection WHERE workspace_id=w AND application_id=a
                    AND projection_generation=m.target_generation AND coordinate_id=e.coordinate_id AND present) THEN
                    RAISE EXCEPTION ''RECONSTRUCTION_VALUE_TYPE_CONFLICT'' USING ERRCODE=''23514'';
                END IF;
                INSERT INTO epm.text_cell_projection(workspace_id,application_id,projection_generation,coordinate_id,present,text_value,change_id,last_revision)
                    VALUES(w,a,m.target_generation,e.coordinate_id,e.present,e.resulting_value,e.change_id,e.committed_revision);
                m.carry:=NULL;
                m.counters:=m.counters||jsonb_build_object(''textRows'',coalesce((m.counters->>''textRows'')::bigint,0)+1);
            END IF;
            m.coordinate_cursor:=e.coordinate_id; m.revision_cursor:=e.committed_revision; m.ordinal_cursor:=e.line_ordinal;
            processed:=processed+1; bytes_used:=bytes_used+event_bytes;
        END LOOP;
        counter_name:=''textEvents''; next_phase:=''detail'';
    ELSIF m.phase=''detail'' THEN
        FOR e IN SELECT * FROM epm.line_detail_event WHERE workspace_id=w AND application_id=a
            AND ROW(coordinate_id,committed_revision)>ROW(m.coordinate_cursor,m.revision_cursor)
            ORDER BY coordinate_id,committed_revision LIMIT 128 LOOP
            event_bytes:=octet_length(to_jsonb(e)::text);
            IF processed>0 AND bytes_used+event_bytes>1048576 THEN exhausted:=false; EXIT; END IF;
            previous:=m.carry;
            PERFORM epm.projection_recovery_receipt(w,a,e.operation_id,e.committed_revision,m.source_commit_revision);
            IF e.prior_items IS DISTINCT FROM (CASE WHEN (previous->>''present'')::boolean THEN previous->''items'' ELSE NULL END)
                OR e.prior_total IS DISTINCT FROM (CASE WHEN (previous->>''present'')::boolean THEN (previous->>''total'')::numeric ELSE NULL END)
                OR e.total IS DISTINCT FROM (SELECT coalesce(sum((x->>''amount'')::numeric),0) FROM jsonb_array_elements(e.items)x) THEN
                RAISE EXCEPTION ''RECONSTRUCTION_DETAIL_LINEAGE_INVALID'' USING ERRCODE=''23514'';
            END IF;
            IF e.present THEN
                SELECT present,resulting_amount INTO numeric_present,numeric_amount FROM epm.numeric_fact_event
                    WHERE workspace_id=w AND application_id=a AND coordinate_id=e.coordinate_id
                    AND committed_revision<=e.committed_revision ORDER BY committed_revision DESC,line_ordinal DESC LIMIT 1;
                IF NOT coalesce(numeric_present,false) OR numeric_amount IS DISTINCT FROM e.total THEN
                    RAISE EXCEPTION ''RECONSTRUCTION_DETAIL_HISTORY_TOTAL_CONFLICT'' USING ERRCODE=''23514'';
                END IF;
            END IF;
            m.carry:=to_jsonb(e);
            IF NOT EXISTS(SELECT 1 FROM epm.line_detail_event WHERE workspace_id=w AND application_id=a
                AND coordinate_id=e.coordinate_id AND committed_revision>e.committed_revision) THEN
                IF e.present THEN
                    IF NOT EXISTS(SELECT 1 FROM epm.numeric_cell_projection WHERE workspace_id=w AND application_id=a
                        AND projection_generation=m.target_generation AND coordinate_id=e.coordinate_id AND present AND amount=e.total) THEN
                        RAISE EXCEPTION ''RECONSTRUCTION_DETAIL_TOTAL_CONFLICT'' USING ERRCODE=''23514'';
                    END IF;
                    INSERT INTO epm.line_detail_projection(workspace_id,application_id,projection_generation,coordinate_id,items,total,change_id,last_revision)
                        VALUES(w,a,m.target_generation,e.coordinate_id,e.items,e.total,e.change_id,e.committed_revision);
                    m.counters:=m.counters||jsonb_build_object(''detailRows'',coalesce((m.counters->>''detailRows'')::bigint,0)+1);
                END IF;
                m.carry:=NULL;
            END IF;
            m.coordinate_cursor:=e.coordinate_id; m.revision_cursor:=e.committed_revision;
            processed:=processed+1; bytes_used:=bytes_used+event_bytes;
        END LOOP;
        counter_name:=''detailEvents''; next_phase:=''generic'';
    ELSIF m.phase=''generic'' THEN
        FOR e IN SELECT * FROM epm.generic_fact_event WHERE workspace_id=w AND application_id=a
            AND ROW(table_id,series_key,committed_revision)>ROW(m.table_cursor,m.key_cursor,m.revision_cursor)
            ORDER BY table_id,series_key,committed_revision LIMIT 128 LOOP
            event_bytes:=octet_length(to_jsonb(e)::text);
            IF processed>0 AND bytes_used+event_bytes>1048576 THEN exhausted:=false; EXIT; END IF;
            previous:=m.carry;
            PERFORM epm.projection_recovery_receipt(w,a,e.operation_id,e.committed_revision,m.source_commit_revision,e.actor_id);
            IF e.before_value IS DISTINCT FROM (CASE WHEN previous->>''action''<>''Delete'' THEN previous->''after_value'' ELSE NULL END)
                OR e.before_change_id IS DISTINCT FROM (CASE WHEN previous->>''action''<>''Delete'' THEN previous->>''resulting_change_id'' ELSE '''' END)
                OR (e.action=''Create'') IS DISTINCT FROM (previous IS NULL OR previous->>''action''=''Delete'')
                OR e.resulting_change_id!~''^[0-9a-f]{32}$''
                OR (e.action=''Delete'' AND e.after_value IS NOT NULL)
                OR (e.action<>''Delete'' AND (e.after_value IS NULL OR e.after_value=''null''::jsonb)) THEN
                RAISE EXCEPTION ''RECONSTRUCTION_GENERIC_LINEAGE_INVALID'' USING ERRCODE=''23514'';
            END IF;
            m.carry:=to_jsonb(e);
            IF NOT EXISTS(SELECT 1 FROM epm.generic_fact_event WHERE workspace_id=w AND application_id=a
                AND table_id=e.table_id AND series_key=e.series_key AND committed_revision>e.committed_revision) THEN
                IF e.action<>''Delete'' THEN
                    INSERT INTO epm.generic_fact_projection(workspace_id,application_id,projection_generation,table_id,series_key,value,change_id,last_revision,updated_at)
                        VALUES(w,a,m.target_generation,e.table_id,e.series_key,e.after_value,e.resulting_change_id,e.committed_revision,e.created_at);
                    m.counters:=m.counters||jsonb_build_object(''genericRows'',coalesce((m.counters->>''genericRows'')::bigint,0)+1);
                END IF;
                m.carry:=NULL;
            END IF;
            m.table_cursor:=e.table_id; m.key_cursor:=e.series_key; m.revision_cursor:=e.committed_revision;
            processed:=processed+1; bytes_used:=bytes_used+event_bytes;
        END LOOP;
        counter_name:=''genericEvents''; next_phase:=''activate'';
    ELSIF m.phase<>''activate'' THEN
        RAISE EXCEPTION ''RECONSTRUCTION_MANIFEST_INVALID'' USING ERRCODE=''23514'';
    END IF;

    \x2d- Flush row checks before changing phase or dropping the capability. Works
    \x2d- both with default deferred constraints and callers requesting IMMEDIATE.
    SET CONSTRAINTS epm.generic_projection_complete IMMEDIATE;
    SET CONSTRAINTS epm.generic_projection_complete DEFERRED;
    IF m.phase<>''activate'' THEN
        m.counters:=m.counters||jsonb_build_object(counter_name,coalesce((m.counters->>counter_name)::bigint,0)+processed);
        \x2d- A completely empty next range is the durable exhaustion certificate.
        \x2d- A full128 batch or byte stop deliberately yields without guessing.
        IF processed=0 AND exhausted THEN
            IF m.carry IS NOT NULL THEN RAISE EXCEPTION ''RECONSTRUCTION_CARRY_INVALID'' USING ERRCODE=''23514''; END IF;
            m.certificates:=m.certificates||jsonb_build_object(m.phase,true);
            m.phase:=next_phase; m.coordinate_cursor:=0; m.revision_cursor:=0; m.ordinal_cursor:=0;
            m.table_cursor:=''''; m.key_cursor:='''';
        END IF;
    END IF;
    m.quantum_count:=m.quantum_count+1;
    \x2d- Keep job unlocked through all source reads/writes so cancellation,
    \x2d- heartbeat and takeover can race; their last committed decision wins here.
    SELECT * INTO j FROM epm.job WHERE workspace_id=w AND application_id=a AND job_id=jid FOR UPDATE;
    IF j.status<>''running'' OR j.claimant IS DISTINCT FROM claimant_name
       OR j.claim_generation IS DISTINCT FROM generation
       OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    UPDATE epm.projection_recovery_manifest SET phase=m.phase,coordinate_cursor=m.coordinate_cursor,
        revision_cursor=m.revision_cursor,ordinal_cursor=m.ordinal_cursor,table_cursor=m.table_cursor,key_cursor=m.key_cursor,
        carry=m.carry,counters=m.counters,certificates=m.certificates,quantum_count=m.quantum_count,
        updated_at=clock_timestamp() WHERE workspace_id=w AND application_id=a AND job_id=jid;
    IF m.phase=''activate'' AND processed=0 AND next_phase IS NULL THEN
        IF m.certificates<>''{"coordinates":true,"numeric":true,"text":true,"detail":true,"generic":true}''::jsonb THEN
            RAISE EXCEPTION ''RECONSTRUCTION_CERTIFICATE_INVALID'' USING ERRCODE=''23514'';
        END IF;
        revision:=s.commit_revision+1;
        output:=jsonb_build_object(''committedRevision'',revision,''sourceCommitRevision'',s.commit_revision,
            ''schemaEpoch'',s.schema_epoch,''reason'',p->>''reason'',''projections'',m.counters,
            ''targetGeneration'',m.target_generation,''historyPreserved'',true);
        UPDATE epm.application_state SET active_projection_generation=m.target_generation,commit_revision=revision
            WHERE workspace_id=w AND application_id=a;
        INSERT INTO epm.operation_receipt(workspace_id,application_id,operation_id,command_digest,actor_id,committed_revision,result)
            VALUES(w,a,jid,j.program_digest,j.subject_id,revision,output);
        UPDATE epm.projection_recovery_manifest SET phase=''published'',context_xid=NULL,context_pid=NULL,context_claim=NULL
            WHERE workspace_id=w AND application_id=a AND job_id=jid;
        UPDATE epm.job SET status=''published'',receipt_revision=revision,result=output,error_code=NULL,
            claimant=NULL,lease_until=NULL,updated_at=clock_timestamp()
            WHERE workspace_id=w AND application_id=a AND job_id=jid;
    ELSE
        output:=jsonb_build_object(''status'',''ready'',''checkpoint'',true,''phase'',m.phase,
            ''processedEvents'',processed,''targetGeneration'',m.target_generation,''quantumCount'',m.quantum_count);
        UPDATE epm.projection_recovery_manifest SET context_xid=NULL,context_pid=NULL,context_claim=NULL,
            last_checkpoint_claimant=claimant_name,last_checkpoint_generation=generation,last_checkpoint_digest=j.program_digest
            WHERE workspace_id=w AND application_id=a AND job_id=jid;
        UPDATE epm.job SET status=''ready'',claimant=NULL,lease_until=NULL,error_code=NULL,
            result=output,attempts=greatest(attempts-1,0),updated_at=clock_timestamp()
            WHERE workspace_id=w AND application_id=a AND job_id=jid;
    END IF;
    PERFORM set_config(''epm.staged_projection_context'','''',true);
    PERFORM set_config(''epm.fact_reconstruction_context'','''',true);
    RETURN output;
END ';

CREATE FUNCTION "epm"."fact_receipt_close"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    PERFORM epm.fact_scope_check(NEW.workspace_id,NEW.application_id);
    UPDATE epm.operation_receipt SET sealed=true WHERE ctid=NEW.ctid
      AND workspace_id=NEW.workspace_id AND application_id=NEW.application_id
      AND operation_id=NEW.operation_id AND NOT sealed;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."fact_receipt_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE head bigint; opened boolean;
BEGIN
    PERFORM epm.fact_scope_check(NEW.workspace_id,NEW.application_id);
    SELECT commit_revision,commit_open INTO head,opened FROM epm.application_state
      WHERE workspace_id=NEW.workspace_id AND application_id=NEW.application_id FOR UPDATE;
    IF TG_OP=''INSERT'' THEN
        IF head IS NULL OR NOT(NEW.committed_revision=head+1 OR (NEW.committed_revision=head AND opened)) THEN
            RAISE EXCEPTION ''FACT_RECEIPT_REVISION_INVALID'' USING ERRCODE=''23514'';
        END IF;
        NEW.sealed=false; RETURN NEW;
    END IF;
    IF OLD.sealed OR NOT NEW.sealed OR (to_jsonb(NEW)-''sealed'') IS DISTINCT FROM (to_jsonb(OLD)-''sealed'') THEN
        RAISE EXCEPTION ''FACT_OPERATION_SEALED'' USING ERRCODE=''23514'';
    END IF;
    IF head<NEW.committed_revision THEN
        RAISE EXCEPTION ''FACT_RECEIPT_REVISION_UNPUBLISHED'' USING ERRCODE=''23514'';
    END IF;
    PERFORM epm.fact_reconcile(NEW.workspace_id,NEW.application_id,NEW.operation_id);
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."forecast_definition_configuration_valid"("c" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE k text; v jsonb; start_day date; cutoff date; end_day date;
BEGIN
 IF jsonb_typeof(c)<>''object'' OR (SELECT count(*) FROM jsonb_object_keys(c))<>14
 OR NOT c ?& ARRAY[''name'',''scenarioDimension'',''actualMember'',''priorForecastMember'',''targetMember'',''yearDimension'',''periodDimension'',''filterMembers'',''mode'',''advancePeriods'',''horizonPeriods'',''windowStart'',''actualThrough'',''windowEndExclusive''] THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY[''name'',''scenarioDimension'',''actualMember'',''priorForecastMember'',''targetMember'',''yearDimension'',''periodDimension''] LOOP
  IF jsonb_typeof(c->k)<>''string'' OR length(c->>k) NOT BETWEEN 1 AND 200 OR btrim(c->>k)<>c->>k OR (c->>k) ~ ''[[:cntrl:]]'' THEN RETURN false; END IF;
 END LOOP;
 IF c->>''mode'' NOT IN (''seed'',''replace'') OR jsonb_typeof(c->''mode'')<>''string''
 OR c->>''scenarioDimension'' IN (c->>''yearDimension'',c->>''periodDimension'') OR c->>''yearDimension''=c->>''periodDimension''
 OR c->>''actualMember'' IN (c->>''priorForecastMember'',c->>''targetMember'') OR c->>''priorForecastMember''=c->>''targetMember'' THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY[''advancePeriods'',''horizonPeriods''] LOOP
  IF jsonb_typeof(c->k)<>''number'' OR (c->>k) !~ ''^[1-9][0-9]?$'' OR (c->>k)::int>36 THEN RETURN false; END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY[''windowStart'',''actualThrough'',''windowEndExclusive''] LOOP
  IF jsonb_typeof(c->k)<>''string'' OR (c->>k) !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' THEN RETURN false; END IF;
 END LOOP;
 start_day=(c->>''windowStart'')::date; cutoff=(c->>''actualThrough'')::date; end_day=(c->>''windowEndExclusive'')::date;
 IF start_day>=end_day OR cutoff<start_day OR cutoff>end_day THEN RETURN false; END IF;
 IF jsonb_typeof(c->''filterMembers'')<>''object'' OR (SELECT count(*) FROM jsonb_object_keys(c->''filterMembers''))>29 THEN RETURN false; END IF;
 FOR k,v IN SELECT * FROM jsonb_each(c->''filterMembers'') LOOP
  IF length(k) NOT BETWEEN 1 AND 200 OR btrim(k)<>k OR k ~ ''[[:cntrl:]]'' OR k IN (c->>''scenarioDimension'',c->>''yearDimension'',c->>''periodDimension'') OR jsonb_typeof(v)<>''string'' OR length(v#>>''{}'') NOT BETWEEN 1 AND 200 OR btrim(v#>>''{}'')<>v#>>''{}'' OR (v#>>''{}'') ~ ''[[:cntrl:]]'' THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END ';

CREATE FUNCTION "epm"."forecast_definition_state_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
 IF current_setting(''epm.workspace_id'',true) IS DISTINCT FROM NEW.workspace_id OR current_setting(''epm.application_id'',true) IS DISTINCT FROM NEW.application_id THEN RAISE EXCEPTION ''FORECAST_DEFINITION_SCOPE_INVALID'' USING ERRCODE=''23514''; END IF;
 IF TG_OP=''INSERT'' THEN
  IF NEW.latest_version<>1 OR NEW.state_revision<>1 OR NEW.active_version IS NOT NULL THEN RAISE EXCEPTION ''FORECAST_DEFINITION_STATE_INVALID'' USING ERRCODE=''23514''; END IF;
 ELSE
  IF ROW(NEW.workspace_id,NEW.application_id,NEW.definition_id) IS DISTINCT FROM ROW(OLD.workspace_id,OLD.application_id,OLD.definition_id) OR NEW.state_revision<>OLD.state_revision+1 OR NOT ((NEW.latest_version=OLD.latest_version+1 AND NEW.active_version IS NOT DISTINCT FROM OLD.active_version) OR (NEW.latest_version=OLD.latest_version AND NEW.active_version IS DISTINCT FROM OLD.active_version)) THEN RAISE EXCEPTION ''FORECAST_DEFINITION_STATE_INVALID'' USING ERRCODE=''23514''; END IF;
 END IF;
 RETURN NEW;
END ';

CREATE FUNCTION "epm"."forecast_definition_version_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE latest bigint;
BEGIN
 IF TG_OP<>''INSERT'' THEN RAISE EXCEPTION ''FORECAST_DEFINITION_IMMUTABLE'' USING ERRCODE=''23514''; END IF;
 IF current_setting(''epm.workspace_id'',true) IS DISTINCT FROM NEW.workspace_id OR current_setting(''epm.application_id'',true) IS DISTINCT FROM NEW.application_id THEN RAISE EXCEPTION ''FORECAST_DEFINITION_SCOPE_INVALID'' USING ERRCODE=''23514''; END IF;
 SELECT latest_version INTO latest FROM epm.planning_forecast_definition_state WHERE workspace_id=NEW.workspace_id AND application_id=NEW.application_id AND definition_id=NEW.definition_id;
 IF NEW.version<>coalesce(latest,0)+1 THEN RAISE EXCEPTION ''FORECAST_DEFINITION_VERSION_INVALID'' USING ERRCODE=''23514''; END IF;
 RETURN NEW;
END ';

CREATE FUNCTION "epm"."forecast_schedule_worker_release"("p_workspace" "text", "p_application" "text", "p_schedule" "text", "p_generation" bigint, "p_claimant" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
  UPDATE epm.planning_forecast_schedule_state SET dispatch_claimant=NULL,
    dispatch_lease_until=NULL,updated_at=transaction_timestamp()
   WHERE workspace_id=p_workspace AND application_id=p_application
     AND schedule_id=p_schedule AND dispatch_generation=p_generation
     AND dispatch_claimant=p_claimant;
  GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1;
END ';

CREATE FUNCTION "epm"."generic_event_provenance_required"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE p jsonb;
BEGIN
    PERFORM epm.fact_scope_check(NEW.workspace_id,NEW.application_id);
    SELECT provenance INTO p FROM epm.operation_receipt WHERE workspace_id=NEW.workspace_id
      AND application_id=NEW.application_id AND operation_id=NEW.operation_id;
    IF p IS NULL THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_REQUIRED'' USING ERRCODE=''23514'';
    END IF;
    IF jsonb_typeof(p->''arguments''->''changes'') IS DISTINCT FROM ''array'' THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->''arguments''->''changes'') c
       WHERE c->>''eventId''=NEW.event_id) THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."generic_fact_event_complete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE r epm.operation_receipt%ROWTYPE; p epm.generic_fact_event%ROWTYPE; head bigint;
BEGIN
    PERFORM epm.fact_scope_check(NEW.workspace_id,NEW.application_id);
    SELECT * INTO r FROM epm.operation_receipt WHERE workspace_id=NEW.workspace_id
      AND application_id=NEW.application_id AND operation_id=NEW.operation_id;
    IF r.operation_id IS NULL THEN
        RAISE EXCEPTION ''GENERIC_FACT_RECEIPT_REQUIRED'' USING ERRCODE=''23514'';
    END IF;
    SELECT commit_revision INTO head FROM epm.application_state WHERE workspace_id=NEW.workspace_id
      AND application_id=NEW.application_id;
    IF NEW.committed_revision<>r.committed_revision OR r.committed_revision>head
       OR NEW.actor_id<>r.actor_id THEN
        RAISE EXCEPTION ''GENERIC_FACT_RECEIPT_MISMATCH'' USING ERRCODE=''23514'';
    END IF;
    SELECT * INTO p FROM epm.generic_fact_event WHERE workspace_id=NEW.workspace_id
      AND application_id=NEW.application_id AND table_id=NEW.table_id AND series_key=NEW.series_key
      AND committed_revision<NEW.committed_revision ORDER BY committed_revision DESC LIMIT 1;
    IF NEW.before_value IS DISTINCT FROM (CASE WHEN p.action<>''Delete'' THEN p.after_value ELSE NULL END)
       OR NEW.before_change_id IS DISTINCT FROM (CASE WHEN p.action<>''Delete'' THEN p.resulting_change_id ELSE '''' END)
       OR (NEW.action=''Create'') IS DISTINCT FROM (p.event_id IS NULL OR p.action=''Delete'') THEN
        RAISE EXCEPTION ''GENERIC_FACT_LINEAGE_INCONSISTENT'' USING ERRCODE=''23514'';
    END IF;
    PERFORM epm.generic_fact_projection_check(NEW.workspace_id,NEW.application_id,NEW.table_id,NEW.series_key);
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."generic_fact_projection_check"("w" "text", "a" "text", "t" "text", "k" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE e epm.generic_fact_event%ROWTYPE; c record;
BEGIN
    PERFORM epm.fact_scope_check(w,a);
    SELECT * INTO e FROM epm.generic_fact_event WHERE workspace_id=w AND application_id=a
      AND table_id=t AND series_key=k ORDER BY committed_revision DESC LIMIT 1;
    SELECT * INTO c FROM epm.generic_fact_current WHERE workspace_id=w AND application_id=a
      AND table_id=t AND series_key=k;
    IF (e.event_id IS NULL AND c.series_key IS NOT NULL)
       OR (e.action=''Delete'' AND c.series_key IS NOT NULL)
       OR (e.action<>''Delete'' AND (c.series_key IS NULL OR
           ROW(c.value,c.change_id,c.last_revision) IS DISTINCT FROM
           ROW(e.after_value,e.resulting_change_id,e.committed_revision))) THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROJECTION_INCONSISTENT'' USING ERRCODE=''23514'';
    END IF;
END ';

CREATE FUNCTION "epm"."generic_fact_projection_complete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE e epm.generic_fact_event%ROWTYPE;
BEGIN
    IF TG_OP=''DELETE'' AND epm.projection_cleanup_allowed(OLD.workspace_id,OLD.application_id,
        OLD.projection_generation,''generic'') THEN RETURN NULL; END IF;
    IF TG_OP<>''DELETE'' AND epm.staged_projection_allowed(NEW.workspace_id,NEW.application_id,
        NEW.projection_generation,''generic'') THEN
        SELECT * INTO e FROM epm.generic_fact_event WHERE workspace_id=NEW.workspace_id
            AND application_id=NEW.application_id AND table_id=NEW.table_id AND series_key=NEW.series_key
            ORDER BY committed_revision DESC LIMIT 1;
        IF e.event_id IS NULL OR e.action=''Delete'' OR ROW(NEW.value,NEW.change_id,NEW.last_revision)
            IS DISTINCT FROM ROW(e.after_value,e.resulting_change_id,e.committed_revision) THEN
            RAISE EXCEPTION ''GENERIC_FACT_PROJECTION_INCONSISTENT'' USING ERRCODE=''23514'';
        END IF;
        RETURN NULL;
    END IF;
    IF TG_OP=''DELETE'' THEN
        PERFORM epm.fact_scope_check(OLD.workspace_id,OLD.application_id);
        IF epm.fact_reconstruction_allowed(OLD.workspace_id,OLD.application_id) THEN
            PERFORM epm.generic_fact_projection_check(OLD.workspace_id,OLD.application_id,OLD.table_id,OLD.series_key);
            RETURN NULL;
        END IF;
        IF NOT EXISTS(SELECT 1 FROM epm.generic_fact_event WHERE workspace_id=OLD.workspace_id
            AND application_id=OLD.application_id AND table_id=OLD.table_id AND series_key=OLD.series_key)
           AND pg_has_role(current_user,(SELECT relowner FROM pg_class
               WHERE oid=''epm.operation_receipt''::regclass),''USAGE'') THEN RETURN NULL; END IF;
        IF NOT EXISTS(SELECT 1 FROM epm.generic_fact_event WHERE workspace_id=OLD.workspace_id
            AND application_id=OLD.application_id AND table_id=OLD.table_id AND series_key=OLD.series_key
            AND action=''Delete'' AND committed_revision>OLD.last_revision) THEN
            RAISE EXCEPTION ''GENERIC_FACT_DELETE_EVENT_REQUIRED'' USING ERRCODE=''23514'';
        END IF;
        PERFORM epm.generic_fact_projection_check(OLD.workspace_id,OLD.application_id,OLD.table_id,OLD.series_key);
    ELSE
        PERFORM epm.generic_fact_projection_check(NEW.workspace_id,NEW.application_id,NEW.table_id,NEW.series_key);
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."generic_fact_write_open"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    \x2d- Serialize with the same short application publication gate as fixed core.
    PERFORM 1 FROM epm.application_state s WHERE EXISTS(SELECT 1 FROM generic_inserted i
       WHERE i.workspace_id=s.workspace_id AND i.application_id=s.application_id) FOR UPDATE;
    IF TG_TABLE_NAME=''generic_fact_event'' THEN
        IF EXISTS(SELECT 1 FROM generic_inserted i JOIN epm.operation_receipt r
           USING(workspace_id,application_id,operation_id) WHERE r.sealed) THEN
            RAISE EXCEPTION ''GENERIC_FACT_OPERATION_SEALED'' USING ERRCODE=''23514'';
        END IF;
        IF EXISTS(SELECT 1 FROM generic_inserted i LEFT JOIN epm.application_state s
           USING(workspace_id,application_id) WHERE s.commit_revision IS NULL OR NOT
           (i.committed_revision=s.commit_revision+1 OR
             (i.committed_revision=s.commit_revision AND s.commit_open))) THEN
            RAISE EXCEPTION ''GENERIC_FACT_REVISION_INVALID'' USING ERRCODE=''23514'';
        END IF;
        IF EXISTS(SELECT 1 FROM generic_inserted i WHERE
           i.resulting_change_id!~''^[0-9a-f]{32}$'' OR
           (i.action=''Create'' AND (i.before_value IS NOT NULL OR i.before_change_id<>'''')) OR
           (i.action IN (''Update'',''Delete'') AND
             (i.before_value IS NULL OR i.before_value=''null''::jsonb OR i.before_change_id!~''^[0-9a-f]{32}$'')) OR
           (i.action=''Delete'' AND i.after_value IS NOT NULL) OR
           (i.action<>''Delete'' AND (i.after_value IS NULL OR i.after_value=''null''::jsonb))) THEN
            RAISE EXCEPTION ''GENERIC_FACT_EVENT_SHAPE_INVALID'' USING ERRCODE=''23514'';
        END IF;
    ELSE
        IF EXISTS(SELECT 1 FROM generic_inserted i LEFT JOIN epm.application_state s
           USING(workspace_id,application_id) WHERE s.commit_revision IS NULL OR NOT
           (epm.fact_reconstruction_allowed(i.workspace_id,i.application_id) OR (i.last_revision=s.commit_revision+1 OR
             (i.last_revision=s.commit_revision AND s.commit_open)))) THEN
            RAISE EXCEPTION ''GENERIC_FACT_PROJECTION_INCONSISTENT'' USING ERRCODE=''23514'';
        END IF;
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."generic_provenance_validate"("w" "text", "a" "text", "op" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE r epm.operation_receipt%ROWTYPE; p jsonb; args jsonb; changes jsonb;
    f text; n integer; expected_keys text[];
BEGIN
    PERFORM epm.fact_scope_check(w,a);
    SELECT * INTO r FROM epm.operation_receipt
      WHERE workspace_id=w AND application_id=a AND operation_id=op;
    IF r.operation_id IS NULL THEN
        RAISE EXCEPTION ''GENERIC_FACT_RECEIPT_REQUIRED'' USING ERRCODE=''23514'';
    END IF;
    p := r.provenance;
    IF p IS NULL THEN RETURN; END IF;
    IF jsonb_typeof(p) IS DISTINCT FROM ''object'' THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF NOT(p ?& ARRAY[''version'',''encoding'',''languageVersion'',''function'',''issuer'',''subjectId'',''arguments''])
       OR p-ARRAY[''version'',''encoding'',''languageVersion'',''function'',''issuer'',''subjectId'',''arguments'']<>''{}''::jsonb
       OR p->''version'' IS DISTINCT FROM ''1''::jsonb
       OR p->''languageVersion'' IS DISTINCT FROM ''2''::jsonb
       OR p->''encoding'' IS DISTINCT FROM ''"generic-event-references-v1"''::jsonb
       OR jsonb_typeof(p->''issuer'') IS DISTINCT FROM ''string'' OR coalesce(p->>''issuer'','''')=''''
       OR jsonb_typeof(p->''subjectId'') IS DISTINCT FROM ''string''
       OR p->>''subjectId'' IS DISTINCT FROM r.actor_id
       OR jsonb_typeof(p->''function'') IS DISTINCT FROM ''string''
       OR jsonb_typeof(p->''arguments'') IS DISTINCT FROM ''object'' THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    f := p->>''function''; args := p->''arguments'';
    IF f IN (''facts.generic.table.create'',''facts.generic.table.update'',''facts.generic.table.delete'') THEN
        expected_keys := CASE f
          WHEN ''facts.generic.table.create'' THEN ARRAY[''name'',''shortDescription'',''semanticDefinition'',''expectedMetadataRevision'']
          WHEN ''facts.generic.table.update'' THEN ARRAY[''tableId'',''name'',''shortDescription'',''semanticDefinition'',''status'',''expectedMetadataRevision'']
          ELSE ARRAY[''tableId'',''expectedMetadataRevision''] END;
        IF NOT(args ?& expected_keys) OR args-expected_keys<>''{}''::jsonb
           OR jsonb_typeof(args->''expectedMetadataRevision'') IS DISTINCT FROM ''number''
           OR coalesce(args->>''expectedMetadataRevision'','''')!~''^(0|[1-9][0-9]*)$'' THEN
            RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
        END IF;
        IF r.result->''metadataRevision'' IS DISTINCT FROM to_jsonb((args->>''expectedMetadataRevision'')::numeric+1)
           OR EXISTS(SELECT 1 FROM epm.generic_fact_event
              WHERE workspace_id=w AND application_id=a AND operation_id=op) THEN
            RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
        END IF;
        IF f<>''facts.generic.table.create'' AND
           (jsonb_typeof(args->''tableId'') IS DISTINCT FROM ''string''
            OR args->>''tableId'' IS DISTINCT FROM r.result->>''tableId'') THEN
            RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
        END IF;
        IF f<>''facts.generic.table.delete'' AND
           (jsonb_typeof(args->''name'') IS DISTINCT FROM ''string''
            OR jsonb_typeof(args->''shortDescription'') IS DISTINCT FROM ''string''
            OR jsonb_typeof(args->''semanticDefinition'') IS DISTINCT FROM ''string''
            OR args->>''name'' IS DISTINCT FROM r.result->>''name'') THEN
            RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
        END IF;
        IF f=''facts.generic.table.update'' AND
           (jsonb_typeof(args->''status'') IS DISTINCT FROM ''string''
            OR args->>''status'' IS DISTINCT FROM r.result->>''status'') THEN
            RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
        END IF;
        RETURN;
    END IF;
    IF f NOT IN (''facts.generic.value.set'',''facts.generic.value.delete'',''facts.generic.value.bulk'')
       OR NOT(args ?& ARRAY[''tableId'',''expectedDataRevision'',''changes''])
       OR args-ARRAY[''tableId'',''expectedDataRevision'',''changes'']<>''{}''::jsonb
       OR jsonb_typeof(args->''tableId'') IS DISTINCT FROM ''string''
       OR args->>''tableId'' IS DISTINCT FROM r.result->>''tableId''
       OR jsonb_typeof(args->''expectedDataRevision'') IS DISTINCT FROM ''number''
       OR coalesce(args->>''expectedDataRevision'','''')!~''^(0|[1-9][0-9]*)$''
       OR jsonb_typeof(args->''changes'') IS DISTINCT FROM ''array'' THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    changes := args->''changes''; n := jsonb_array_length(changes);
    IF n NOT BETWEEN 1 AND 100 OR (f<>''facts.generic.value.bulk'' AND n<>1)
       OR r.result->''dataRevision'' IS DISTINCT FROM to_jsonb((args->>''expectedDataRevision'')::numeric+1)
       OR (SELECT count(*) FROM epm.generic_fact_event
           WHERE workspace_id=w AND application_id=a AND operation_id=op)<>n THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF f=''facts.generic.value.bulk'' AND
       (jsonb_typeof(r.result->''changes'') IS DISTINCT FROM ''array''
        OR jsonb_array_length(r.result->''changes'')<>n) THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    \x2d- Validate the ordered descriptor in sets; never issue one SQL query per cell.
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(changes) c
       WHERE jsonb_typeof(c) IS DISTINCT FROM ''object'') THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(changes) c
       WHERE jsonb_typeof(c->''action'') IS DISTINCT FROM ''string''
          OR coalesce(c->>''action'','''') NOT IN (''Set'',''Delete'')
          OR NOT(c ?& CASE WHEN c->>''action''=''Set''
             THEN ARRAY[''action'',''seriesKey'',''expectedChangeId'',''eventId'',''valueField'']
             ELSE ARRAY[''action'',''seriesKey'',''expectedChangeId'',''eventId''] END)
          OR c-(CASE WHEN c->>''action''=''Set''
             THEN ARRAY[''action'',''seriesKey'',''expectedChangeId'',''eventId'',''valueField'']
             ELSE ARRAY[''action'',''seriesKey'',''expectedChangeId'',''eventId''] END)<>''{}''::jsonb
          OR jsonb_typeof(c->''seriesKey'') IS DISTINCT FROM ''string''
          OR jsonb_typeof(c->''expectedChangeId'') IS DISTINCT FROM ''string''
          OR jsonb_typeof(c->''eventId'') IS DISTINCT FROM ''string''
          OR coalesce(c->>''eventId'','''')!~''^[0-9a-f]{32}$''
          OR (c->>''action''=''Set'' AND c->''valueField'' IS DISTINCT FROM ''"after_value"''::jsonb)
          OR (f=''facts.generic.value.set'' AND c->>''action''<>''Set'')
          OR (f=''facts.generic.value.delete'' AND c->>''action''<>''Delete''))
       OR (SELECT count(DISTINCT c->>''eventId'') FROM jsonb_array_elements(changes)c)<>n THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF EXISTS(WITH refs AS(SELECT value AS c,ordinality AS ordinal,
         CASE WHEN f=''facts.generic.value.bulk''
           THEN r.result->''changes''->((ordinality-1)::integer) ELSE r.result END AS output
         FROM jsonb_array_elements(changes) WITH ORDINALITY)
       SELECT 1 FROM refs i LEFT JOIN epm.generic_fact_event e
         ON e.workspace_id=w AND e.application_id=a AND e.operation_id=op AND e.event_id=i.c->>''eventId''
       WHERE e.event_id IS NULL OR e.table_id IS DISTINCT FROM args->>''tableId''
          OR e.series_key IS DISTINCT FROM i.c->>''seriesKey''
          OR e.before_change_id IS DISTINCT FROM i.c->>''expectedChangeId''
          OR (e.action=''Delete'') IS DISTINCT FROM (i.c->>''action''=''Delete'')
          OR e.actor_id IS DISTINCT FROM p->>''subjectId''
          OR e.committed_revision<>r.committed_revision
          OR i.output->>''seriesKey'' IS DISTINCT FROM e.series_key
          OR i.output->''deleted'' IS DISTINCT FROM to_jsonb(e.action=''Delete'')
          OR i.output->>''changeId'' IS DISTINCT FROM CASE WHEN e.action=''Delete'' THEN '''' ELSE e.resulting_change_id END) THEN
        RAISE EXCEPTION ''GENERIC_FACT_PROVENANCE_INVALID'' USING ERRCODE=''23514'';
    END IF;
END ';

CREATE FUNCTION "epm"."generic_receipt_provenance_complete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    IF NEW.provenance IS NOT NULL THEN
        PERFORM epm.generic_provenance_validate(NEW.workspace_id,NEW.application_id,NEW.operation_id);
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."hierarchy_activate_complete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE published boolean;
BEGIN
    SELECT sealed INTO published FROM epm.hierarchy_version WHERE workspace_id=NEW.workspace_id
      AND application_id=NEW.application_id AND dimension_id=NEW.dimension_id AND version=NEW.version;
    IF published IS NULL OR NOT epm.hierarchy_publication_complete(NEW.workspace_id,NEW.application_id,NEW.dimension_id,NEW.version) THEN
        RAISE EXCEPTION ''HIERARCHY_VERSION_INCOMPLETE'' USING ERRCODE=''23514'';
    END IF;
    IF published AND (TG_OP=''INSERT'' OR OLD.version<>NEW.version) THEN
        RAISE EXCEPTION ''HIERARCHY_VERSION_SEALED'' USING ERRCODE=''23514'';
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."hierarchy_closure_open"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    IF EXISTS(SELECT 1 FROM hierarchy_inserted i JOIN epm.hierarchy_version h
        USING(workspace_id,application_id,dimension_id,version) WHERE h.sealed) THEN
        RAISE EXCEPTION ''HIERARCHY_VERSION_SEALED'' USING ERRCODE=''23514'';
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."hierarchy_seal_active"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    UPDATE epm.hierarchy_version SET sealed=true WHERE workspace_id=NEW.workspace_id
      AND application_id=NEW.application_id AND dimension_id=NEW.dimension_id AND version=NEW.version AND NOT sealed;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."hierarchy_version_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    IF TG_OP=''INSERT'' THEN NEW.sealed=false; RETURN NEW; END IF;
    IF OLD.sealed OR NOT NEW.sealed OR
       (to_jsonb(NEW)-''sealed'') IS DISTINCT FROM (to_jsonb(OLD)-''sealed'') THEN
        RAISE EXCEPTION ''HIERARCHY_VERSION_SEALED'' USING ERRCODE=''23514'';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM epm.hierarchy_active p WHERE p.workspace_id=NEW.workspace_id
        AND p.application_id=NEW.application_id AND p.dimension_id=NEW.dimension_id AND p.version=NEW.version)
       OR NOT epm.hierarchy_publication_complete(NEW.workspace_id,NEW.application_id,NEW.dimension_id,NEW.version) THEN
        RAISE EXCEPTION ''HIERARCHY_VERSION_UNPUBLISHED'' USING ERRCODE=''23514'';
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."hierarchy_version_must_seal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
    IF EXISTS(SELECT 1 FROM epm.hierarchy_version h WHERE h.workspace_id=NEW.workspace_id
      AND h.application_id=NEW.application_id AND h.dimension_id=NEW.dimension_id AND h.version=NEW.version AND NOT h.sealed) THEN
        RAISE EXCEPTION ''HIERARCHY_VERSION_UNPUBLISHED'' USING ERRCODE=''23514'';
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."inventory_unrealized_legacy_line_forbidden"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
BEGIN
 IF EXISTS(SELECT 1 FROM inventory_unrealized_legacy_inserted i
  JOIN epm.calculation_generation g USING(workspace_id,application_id,generation_id)
  WHERE g.function_name=''consolidation.inventory.unrealized_profit.request'') THEN
  RAISE EXCEPTION ''INVENTORY_UNREALIZED_TYPED_STORAGE_REQUIRED'' USING ERRCODE=''23514'';
 END IF;
 RETURN NULL;
END';

CREATE FUNCTION "epm"."layout_activation_added_axis_receipt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE added_axis text;
BEGIN
 SELECT r.plan->''targetMetadata''->''dimension''->>''dimensionId'' INTO added_axis
 FROM epm.layout_replacement_activation x
 JOIN epm.layout_replacement_request r USING(workspace_id,application_id,request_id)
 WHERE x.workspace_id=NEW.workspace_id AND x.application_id=NEW.application_id
 AND x.activation_id=NEW.operation_id AND x.status=''Activating''
 AND epm.layout_replacement_activation_allowed(x.workspace_id,x.application_id,
     x.target_projection_generation,''activate'');
 IF added_axis IS NOT NULL THEN
  NEW.result:=NEW.result||jsonb_build_object(''addedDimensionId'',added_axis);
 END IF;
 RETURN NEW;
END ';

CREATE FUNCTION "epm"."layout_activation_receipt_replay"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE prior epm.operation_receipt%ROWTYPE;
BEGIN
    SELECT r.* INTO prior FROM epm.operation_receipt r
      JOIN epm.layout_replacement_activation x
        ON x.workspace_id=r.workspace_id AND x.application_id=r.application_id
       AND x.activation_id=r.operation_id
     WHERE r.workspace_id=NEW.workspace_id AND r.application_id=NEW.application_id
       AND r.operation_id=NEW.operation_id AND x.status=''Activating''
       AND epm.layout_replacement_activation_allowed(
           x.workspace_id,x.application_id,x.target_projection_generation,''activate'');
    IF FOUND THEN
        IF (to_jsonb(prior)-''sealed''-''committed_at'')
           IS DISTINCT FROM (to_jsonb(NEW)-''sealed''-''committed_at'') THEN
            RAISE EXCEPTION ''LAYOUT_ACTIVATION_RECEIPT_CONFLICT'';
        END IF;
        RETURN NULL;
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."layout_replacement_activation_allowed"("w" "text", "a" "text", "target" bigint, "phase" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E' DECLARE x epm.layout_replacement_activation%ROWTYPE;BEGIN
 IF coalesce(current_setting(''epm.layout_activation_context'',true),'''')='''' OR
 NOT pg_has_role(current_user,(SELECT relowner FROM pg_class WHERE oid=''epm.operation_receipt''::regclass),''USAGE'') THEN RETURN false;END IF;
 SELECT * INTO x FROM epm.layout_replacement_activation WHERE workspace_id=w AND application_id=a
  AND target_projection_generation=target AND status=''Activating'' AND claimant IS NOT NULL
  AND lease_until>clock_timestamp() AND current_setting(''epm.layout_activation_context'',true)=jsonb_build_array(
   w,a,activation_id,target_projection_generation,claim_generation,pg_current_xact_id()::text,pg_backend_pid())::text;
 RETURN FOUND;
END ';

CREATE FUNCTION "epm"."layout_replacement_activation_cancel"("w" "text", "a" "text", "aid" "text", "expected_status" "text", "expected_version" bigint) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE n integer;
BEGIN
    IF w<>current_setting(''epm.workspace_id'',true)
       OR a<>current_setting(''epm.application_id'',true) THEN
        RAISE EXCEPTION ''LAYOUT_ACTIVATION_SCOPE_INVALID'';
    END IF;
    IF expected_status<>''Requested'' OR expected_version<0 THEN
        RAISE EXCEPTION ''LAYOUT_ACTIVATION_CANCEL_INVALID'';
    END IF;
    UPDATE epm.layout_replacement_activation
       SET status=''Cancelled'',claim_generation=claim_generation+1,
           claimant=NULL,lease_until=NULL,updated_at=transaction_timestamp()
     WHERE workspace_id=w AND application_id=a AND activation_id=aid
       AND status=expected_status AND claim_generation=expected_version;
    GET DIAGNOSTICS n=ROW_COUNT;
    RETURN n=1;
END ';

CREATE FUNCTION "epm"."layout_replacement_activation_publish"("w" "text", "a" "text", "aid" "text", "claimant_name" "text", "generation" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE x epm.layout_replacement_activation%ROWTYPE;s epm.application_state%ROWTYPE;cert epm.layout_replacement_validation_certificate%ROWTYPE;
 layout epm.coordinate_layout%ROWTYPE;revision bigint;outcome jsonb;plan jsonb;proposed jsonb;new_axis text;BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended(''epm.security.workspace:''||w,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(''epm.application:''||w||'':''||a,0));
 SELECT * INTO x FROM epm.layout_replacement_activation WHERE workspace_id=w AND application_id=a AND activation_id=aid FOR UPDATE;
 SELECT * INTO s FROM epm.application_state WHERE workspace_id=w AND application_id=a FOR UPDATE;
 SELECT * INTO cert FROM epm.layout_replacement_validation_certificate WHERE workspace_id=w AND application_id=a AND request_id=x.request_id;
 SELECT r.plan INTO plan FROM epm.layout_replacement_request r WHERE r.workspace_id=w AND r.application_id=a AND r.request_id=x.request_id;
 IF x.status=''Activated'' AND x.claim_generation=generation THEN RETURN x.result;END IF;
 IF x.status<>''Activating'' OR x.claimant<>claimant_name OR x.claim_generation<>generation OR x.lease_until<=clock_timestamp()
 THEN RAISE EXCEPTION ''LAYOUT_ACTIVATION_STALE_WORKER'';END IF;
 IF NOT cert.activation_eligible OR cert.validation_digest<>x.validation_digest OR s.commit_open OR s.processing_mode<>''Active''
  OR ROW(s.metadata_revision,s.data_revision,s.policy_revision,s.schema_epoch,s.commit_revision,s.active_projection_generation)
  IS DISTINCT FROM ROW(x.source_metadata_revision,x.source_data_revision,x.source_policy_revision,x.source_schema_epoch,x.source_commit_revision,x.source_projection_generation)
  OR NOT EXISTS(SELECT 1 FROM epm.workspace WHERE workspace_id=w AND status=''Active'')
  OR NOT EXISTS(SELECT 1 FROM epm.application WHERE workspace_id=w AND application_id=a AND status=''Active'')
  OR (NOT EXISTS(SELECT 1 FROM epm.workspace_access_grant WHERE workspace_id=w AND issuer=x.issuer AND subject_id=x.subject_id AND role=''Administrator'')
      AND NOT EXISTS(SELECT 1 FROM epm.application_access_grant WHERE workspace_id=w AND application_id=a AND issuer=x.issuer AND subject_id=x.subject_id AND role=''Administrator''))
 THEN RAISE EXCEPTION ''LAYOUT_ACTIVATION_STALE'';END IF;
 IF EXISTS(SELECT 1 FROM epm.job WHERE workspace_id=w AND application_id=a AND status IN(''accepted'',''ready'',''running'',''staged'',''cancel_requested'',''needs_inspection''))
  OR EXISTS(SELECT 1 FROM epm.source_batch WHERE workspace_id=w AND application_id=a AND status IN(''staging'',''ready''))
  OR EXISTS(SELECT 1 FROM epm.expression_rule_sequence WHERE workspace_id=w AND application_id=a AND status IN(''accepted'',''running'',''cancel_requested''))
  OR EXISTS(SELECT 1 FROM epm.full_aggregate_sequence WHERE workspace_id=w AND application_id=a AND status IN(''accepted'',''running'',''cancel_requested''))
 THEN RAISE EXCEPTION ''LAYOUT_ACTIVATION_CONFLICTING_WORK'';END IF;
 PERFORM set_config(''epm.layout_activation_context'',jsonb_build_array(w,a,aid,x.target_projection_generation,generation,pg_current_xact_id()::text,pg_backend_pid())::text,true);
 proposed:=plan->''targetMetadata'';
 IF proposed IS NOT NULL THEN
  new_axis:=proposed->''dimension''->>''dimensionId'';
  IF plan->>''format''<>''openepm-populated-layout-plan-v2'' OR new_axis IS NULL
   OR proposed->''dimension''->>''modelRole''<>''Custom''
   OR jsonb_typeof(proposed->''dimension''->''members'')<>''array''
   OR jsonb_array_length(proposed->''dimension''->''members'') NOT BETWEEN 1 AND 10000
   OR EXISTS(SELECT 1 FROM epm.dimension WHERE workspace_id=w AND application_id=a AND (dimension_id=new_axis OR lower(name)=lower(proposed->''dimension''->>''name'')))
   OR EXISTS(SELECT 1 FROM epm.layout_replacement_private_coordinate p WHERE p.workspace_id=w AND p.application_id=a AND p.generation_id=cert.generation_id AND NOT p.target_members ? new_axis)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(proposed->''dimension''->''members'') m WHERE NOT EXISTS(SELECT 1 FROM epm.layout_replacement_private_coordinate p WHERE p.workspace_id=w AND p.application_id=a AND p.generation_id=cert.generation_id AND p.target_members->>new_axis=m->>''memberId''))
   OR EXISTS(SELECT 1 FROM epm.layout_replacement_private_coordinate p WHERE p.workspace_id=w AND p.application_id=a AND p.generation_id=cert.generation_id AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(proposed->''dimension''->''members'') m WHERE m->>''memberId''=p.target_members->>new_axis))
  THEN RAISE EXCEPTION ''LAYOUT_ADDED_AXIS_METADATA_STALE_OR_INVALID'';END IF;
  INSERT INTO epm.dimension(workspace_id,application_id,dimension_id,name,model_role,short_description,detailed_description)
  VALUES(w,a,new_axis,proposed->''dimension''->>''name'',''Custom'',proposed->''dimension''->>''shortDescription'',proposed->''dimension''->>''detailedDescription'');
  INSERT INTO epm.member(workspace_id,application_id,dimension_id,member_id,name,short_description,detailed_description)
  SELECT w,a,new_axis,m->>''memberId'',m->>''name'',m->>''shortDescription'',m->>''detailedDescription''
  FROM jsonb_array_elements(proposed->''dimension''->''members'') m;
 END IF;
 UPDATE epm.dimension SET status=CASE WHEN dimension_id IN(SELECT z->>''dimensionId'' FROM jsonb_array_elements(plan->''targetAxes'')z) THEN ''Active'' ELSE ''Inactive'' END
 WHERE workspace_id=w AND application_id=a AND model_role IS DISTINCT FROM ''Currency'';
 SELECT x.target_schema_epoch,ARRAY(SELECT z->>''dimensionId'' FROM jsonb_array_elements(plan->''targetAxes'')z ORDER BY z->>''dimensionId''),
  coalesce(jsonb_object_agg(d.model_role,d.dimension_id)FILTER(WHERE d.model_role IS NOT NULL AND d.model_role<>''Custom''),''{}''),
  coalesce(array_agg(d.dimension_id ORDER BY d.dimension_id)FILTER(WHERE d.model_role IS NULL OR d.model_role=''Custom''),''{}'')
 INTO layout.schema_epoch,layout.dimensions,layout.role_dimensions,layout.custom_dimensions FROM epm.dimension d
 WHERE d.workspace_id=w AND d.application_id=a AND d.status=''Active'' AND d.model_role IS DISTINCT FROM ''Currency'';
 INSERT INTO epm.coordinate_layout VALUES(w,a,layout.schema_epoch,layout.dimensions,layout.role_dimensions,layout.custom_dimensions);
 INSERT INTO epm.coordinate(workspace_id,application_id,series_key,members)
 SELECT w,a,epm.coordinate_series_key(p.target_members),p.target_members FROM epm.layout_replacement_private_coordinate p
 WHERE p.workspace_id=w AND p.application_id=a AND p.generation_id=cert.generation_id ON CONFLICT DO NOTHING;
 INSERT INTO epm.layout_replacement_activation_coordinate SELECT w,a,aid,p.target_digest,c.coordinate_id
 FROM epm.layout_replacement_private_coordinate p JOIN epm.coordinate c ON c.workspace_id=p.workspace_id AND c.application_id=p.application_id AND c.series_key=epm.coordinate_series_key(p.target_members)
 WHERE p.workspace_id=w AND p.application_id=a AND p.generation_id=cert.generation_id;
 INSERT INTO epm.coordinate_member_projection(projection_generation,workspace_id,application_id,coordinate_id,dimension_id,member_id)
 SELECT x.target_projection_generation,w,a,m.coordinate_id,z.key,z.value FROM epm.layout_replacement_activation_coordinate m
 JOIN epm.layout_replacement_private_coordinate p USING(workspace_id,application_id,target_digest),LATERAL jsonb_each_text(p.target_members)z
 WHERE m.workspace_id=w AND m.application_id=a AND m.activation_id=aid;
 INSERT INTO epm.coordinate_projection_state(projection_generation,workspace_id,application_id,coordinate_id,schema_epoch,fact_table_id,entity_member,account_member,scenario_member,year_member,period_member,value_member,view_member,icp_member,data_type_member,custom_members)
 SELECT x.target_projection_generation,w,a,m.coordinate_id,x.target_schema_epoch,''cube'',p.target_members->>(layout.role_dimensions->>''Entity''),p.target_members->>(layout.role_dimensions->>''Account''),p.target_members->>(layout.role_dimensions->>''Scenario''),p.target_members->>(layout.role_dimensions->>''Year''),p.target_members->>(layout.role_dimensions->>''Period''),p.target_members->>(layout.role_dimensions->>''Value''),p.target_members->>(layout.role_dimensions->>''View''),p.target_members->>(layout.role_dimensions->>''ICP''),p.target_members->>(layout.role_dimensions->>''DataType''),ARRAY(SELECT p.target_members->>d FROM unnest(layout.custom_dimensions)d)
 FROM epm.layout_replacement_activation_coordinate m JOIN epm.layout_replacement_private_coordinate p USING(workspace_id,application_id,target_digest)
 WHERE m.workspace_id=w AND m.application_id=a AND m.activation_id=aid;
 revision:=s.commit_revision+1;
 INSERT INTO epm.numeric_cell_projection SELECT w,a,m.coordinate_id,n.present,n.amount,''layout:''||aid,revision,x.target_projection_generation FROM epm.layout_replacement_activation_coordinate m JOIN epm.layout_replacement_private_numeric n USING(workspace_id,application_id,target_digest) WHERE m.workspace_id=w AND m.application_id=a AND m.activation_id=aid;
 INSERT INTO epm.text_cell_projection SELECT w,a,m.coordinate_id,t.present,t.text_value,''layout:''||aid,revision,x.target_projection_generation FROM epm.layout_replacement_activation_coordinate m JOIN epm.layout_replacement_private_text t USING(workspace_id,application_id,target_digest) WHERE m.workspace_id=w AND m.application_id=a AND m.activation_id=aid;
 INSERT INTO epm.line_detail_projection SELECT w,a,m.coordinate_id,d.items,d.total,''layout:''||aid,revision,x.target_projection_generation FROM epm.layout_replacement_activation_coordinate m JOIN epm.layout_replacement_private_detail d USING(workspace_id,application_id,target_digest) WHERE m.workspace_id=w AND m.application_id=a AND m.activation_id=aid AND d.present;
 INSERT INTO epm.generic_fact_projection SELECT w,a,g.table_id,g.series_key,g.value,g.change_id,g.last_revision,g.updated_at,x.target_projection_generation FROM epm.generic_fact_projection g WHERE g.workspace_id=w AND g.application_id=a AND g.projection_generation=x.source_projection_generation;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(x.dependency_decisions)d WHERE d->>''decision'' IN(''Invalidate'',''Rebuild'') AND ((d->>''kind''=''rule'' AND NOT EXISTS(SELECT 1 FROM epm.expression_rule_publication p WHERE p.workspace_id=w AND p.application_id=a AND p.rule_id=d->>''id'')) OR(d->>''kind''=''publication'' AND NOT EXISTS(SELECT 1 FROM epm.calculation_publication p WHERE p.workspace_id=w AND p.application_id=a AND p.result_key=d->>''id'')))) THEN RAISE EXCEPTION ''LAYOUT_ACTIVATION_DEPENDENCY_UNRESOLVED'';END IF;
 DELETE FROM epm.expression_rule_publication p USING jsonb_array_elements(x.dependency_decisions)d WHERE p.workspace_id=w AND p.application_id=a AND d->>''kind''=''rule'' AND d->>''decision'' IN(''Invalidate'',''Rebuild'') AND p.rule_id=d->>''id'';
 DELETE FROM epm.calculation_publication p USING jsonb_array_elements(x.dependency_decisions)d WHERE p.workspace_id=w AND p.application_id=a AND d->>''kind''=''publication'' AND d->>''decision'' IN(''Invalidate'',''Rebuild'') AND p.result_key=d->>''id'';
 UPDATE epm.application_state SET schema_epoch=x.target_schema_epoch,metadata_revision=metadata_revision+1,data_revision=data_revision+1,active_projection_generation=x.target_projection_generation,commit_revision=revision WHERE workspace_id=w AND application_id=a;
 outcome:=jsonb_build_object(''activationId'',aid,''requestId'',x.request_id,''committedRevision'',revision,''schemaEpoch'',x.target_schema_epoch,''projectionGeneration'',x.target_projection_generation,''historyPreserved'',true);
 IF new_axis IS NOT NULL THEN outcome:=outcome||jsonb_build_object(''addedDimensionId'',new_axis);END IF;
 INSERT INTO epm.operation_receipt(workspace_id,application_id,operation_id,command_digest,actor_id,committed_revision,result) VALUES(w,a,aid,x.validation_digest,x.subject_id,revision,outcome);
 UPDATE epm.layout_replacement_activation SET status=''Activated'',result=outcome,claimant=NULL,lease_until=NULL,updated_at=transaction_timestamp() WHERE workspace_id=w AND application_id=a AND activation_id=aid;
 RETURN outcome;END ';

CREATE FUNCTION "epm"."layout_replacement_activation_request"("w" "text", "a" "text", "aid" "text", "rid" "text", "ikey" "text", "rdigest" "text", "issuer_name" "text", "subject_name" "text", "vdigest" "text", "decisions" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE prior epm.layout_replacement_activation%ROWTYPE;s epm.application_state%ROWTYPE;c epm.layout_replacement_validation_certificate%ROWTYPE;
 target_gen bigint;BEGIN
 IF w<>current_setting(''epm.workspace_id'',true) OR a<>current_setting(''epm.application_id'',true) THEN RAISE EXCEPTION ''LAYOUT_ACTIVATION_SCOPE_INVALID'';END IF;
 SELECT * INTO prior FROM epm.layout_replacement_activation WHERE workspace_id=w AND application_id=a
  AND issuer=issuer_name AND subject_id=subject_name AND idempotency_key=ikey;
 IF FOUND THEN IF prior.request_digest<>rdigest THEN RAISE EXCEPTION ''LAYOUT_ACTIVATION_IDEMPOTENCY_CONFLICT'';END IF;
  RETURN jsonb_build_object(''activationId'',prior.activation_id,''status'',prior.status,''duplicate'',true);END IF;
 SELECT * INTO s FROM epm.application_state WHERE workspace_id=w AND application_id=a FOR SHARE;
 SELECT * INTO c FROM epm.layout_replacement_validation_certificate WHERE workspace_id=w AND application_id=a AND request_id=rid;
 IF NOT FOUND OR NOT c.activation_eligible OR c.validation_digest<>vdigest OR s.commit_open
  OR ROW(s.metadata_revision,s.data_revision,s.policy_revision,s.schema_epoch,s.commit_revision)
   IS DISTINCT FROM ROW(c.metadata_revision,c.data_revision,c.policy_revision,c.schema_epoch,c.source_commit_revision)
  OR NOT EXISTS(SELECT 1 FROM epm.layout_replacement_request r WHERE r.workspace_id=w AND r.application_id=a AND r.request_id=rid AND r.status=''Validated'')
 THEN RAISE EXCEPTION ''LAYOUT_ACTIVATION_VALIDATION_STALE'';END IF;
 SELECT greatest(s.active_projection_generation,coalesce(max(target_projection_generation),0))+1 INTO target_gen
  FROM epm.layout_replacement_activation WHERE workspace_id=w AND application_id=a;
 INSERT INTO epm.layout_replacement_activation(workspace_id,application_id,activation_id,request_id,idempotency_key,
  request_digest,issuer,subject_id,validation_digest,source_schema_epoch,target_schema_epoch,source_projection_generation,
  target_projection_generation,source_metadata_revision,source_data_revision,source_policy_revision,source_commit_revision,dependency_decisions)
 VALUES(w,a,aid,rid,ikey,rdigest,issuer_name,subject_name,vdigest,s.schema_epoch,s.schema_epoch+1,
  s.active_projection_generation,target_gen,s.metadata_revision,s.data_revision,s.policy_revision,s.commit_revision,decisions);
 RETURN jsonb_build_object(''activationId'',aid,''status'',''Requested'',''duplicate'',false,''targetSchemaEpoch'',s.schema_epoch+1,
  ''targetProjectionGeneration'',target_gen);END ';

CREATE FUNCTION "epm"."layout_replacement_cancel"("p_workspace" "text", "p_application" "text", "p_request" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
 IF p_workspace IS DISTINCT FROM current_setting(''epm.workspace_id'',true)
 OR p_application IS DISTINCT FROM current_setting(''epm.application_id'',true) THEN
  RAISE EXCEPTION ''LAYOUT_REPLACEMENT_SCOPE_INVALID'' USING ERRCODE=''22023''; END IF;
 UPDATE epm.layout_replacement_request SET status=''Cancelled'',
  claim_generation=claim_generation+1,claimant=NULL,lease_until=NULL,
  updated_at=transaction_timestamp()
 WHERE workspace_id=p_workspace AND application_id=p_application
  AND request_id=p_request AND status IN (''Accepted'',''Staging'');
 GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1;
END ';

CREATE FUNCTION "epm"."layout_replacement_materialization_chunk"("p_workspace" "text", "p_application" "text", "p_request" "text", "p_claimant" "text", "p_generation" bigint, "p_chunk" integer, "p_digest" "text", "p_rows" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE prior text;row_count integer;g text;
BEGIN
 IF p_chunk<0 OR p_digest !~ ''^[0-9a-f]{64}$'' OR jsonb_typeof(p_rows)<>''array''
 OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 THEN
  RAISE EXCEPTION ''LAYOUT_MATERIALIZATION_CHUNK_INVALID'' USING ERRCODE=''22023''; END IF;
 SELECT generation_id INTO g FROM epm.layout_replacement_materialization WHERE
  workspace_id=p_workspace AND application_id=p_application AND request_id=p_request
  AND status=''Running'' AND claimant=p_claimant AND claim_generation=p_generation
  AND lease_until>clock_timestamp();
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT content_digest INTO prior FROM epm.layout_replacement_materialization_chunk
  WHERE workspace_id=p_workspace AND application_id=p_application
  AND request_id=p_request AND chunk_index=p_chunk;
 IF FOUND THEN
  IF prior<>p_digest THEN RAISE EXCEPTION ''LAYOUT_MATERIALIZATION_CHUNK_CONFLICT''; END IF;
  RETURN true;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM epm.layout_replacement_materialization WHERE
  workspace_id=p_workspace AND application_id=p_application AND request_id=p_request
  AND next_chunk=p_chunk) THEN RETURN false; END IF;
 INSERT INTO epm.layout_replacement_private_coordinate
  (workspace_id,application_id,generation_id,target_digest,target_members,source_coordinate_ids)
 SELECT p_workspace,p_application,g,x->>''targetDigest'',x->''targetMembers'',
  ARRAY(SELECT jsonb_array_elements_text(x->''sourceCoordinateIds'')::bigint ORDER BY 1)
 FROM jsonb_array_elements(p_rows) x;
 INSERT INTO epm.layout_replacement_private_numeric
 SELECT p_workspace,p_application,g,x->>''targetDigest'',(x->''numeric''->>''present'')::boolean,
  CASE WHEN (x->''numeric''->>''present'')::boolean THEN (x->''numeric''->>''amount'')::numeric ELSE NULL END
 FROM jsonb_array_elements(p_rows) x;
 INSERT INTO epm.layout_replacement_private_text
 SELECT p_workspace,p_application,g,x->>''targetDigest'',(x->''text''->>''present'')::boolean,
  CASE WHEN (x->''text''->>''present'')::boolean THEN x->''text''->>''value'' ELSE NULL END
 FROM jsonb_array_elements(p_rows) x;
 INSERT INTO epm.layout_replacement_private_detail
 SELECT p_workspace,p_application,g,x->>''targetDigest'',(x->''detail''->>''present'')::boolean,
  CASE WHEN (x->''detail''->>''present'')::boolean THEN x->''detail''->''items'' ELSE NULL END,
  CASE WHEN (x->''detail''->>''present'')::boolean THEN (x->''detail''->>''total'')::numeric ELSE NULL END
 FROM jsonb_array_elements(p_rows) x;
 row_count:=jsonb_array_length(p_rows);
 INSERT INTO epm.layout_replacement_materialization_chunk VALUES
  (p_workspace,p_application,p_request,p_chunk,p_digest,row_count,transaction_timestamp());
 UPDATE epm.layout_replacement_materialization SET next_chunk=next_chunk+1,
  target_count=target_count+row_count,lease_until=clock_timestamp()+interval ''120 seconds'',
  updated_at=transaction_timestamp()
 WHERE workspace_id=p_workspace AND application_id=p_application AND request_id=p_request;
 RETURN true;
END ';

CREATE FUNCTION "epm"."layout_replacement_staged_count"("p_workspace" "text", "p_application" "text", "p_request" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE v_generation text;
DECLARE v_expected integer;
DECLARE v_count bigint;
BEGIN
    IF p_workspace IS DISTINCT FROM current_setting(''epm.workspace_id'',true)
       OR p_application IS DISTINCT FROM current_setting(
           ''epm.application_id'',true) THEN
        RAISE EXCEPTION ''LAYOUT_REPLACEMENT_SCOPE_INVALID''
            USING ERRCODE=''42501'';
    END IF;
    SELECT r.target_generation_id,r.expected_coordinate_count
      INTO v_generation,v_expected
      FROM epm.layout_replacement_request r
     WHERE r.workspace_id=p_workspace AND r.application_id=p_application
       AND r.request_id=p_request;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    SELECT count(*) INTO v_count
      FROM epm.layout_replacement_staged_coordinate c
     WHERE c.workspace_id=p_workspace AND c.application_id=p_application
       AND c.generation_id=v_generation;
    IF v_count>v_expected OR v_count>100000 THEN
        RAISE EXCEPTION ''LAYOUT_REPLACEMENT_STAGED_COUNT_INVALID'';
    END IF;
    RETURN v_count::integer;
END ';

CREATE FUNCTION "epm"."layout_replacement_staged_mapping"("p_workspace" "text", "p_application" "text", "p_request" "text") RETURNS TABLE("source_coordinate_id" bigint, "target_members" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER ROWS 100000
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE v_generation text;
DECLARE v_expected integer;
DECLARE v_count bigint;
BEGIN
    IF p_workspace IS DISTINCT FROM current_setting(''epm.workspace_id'',true)
       OR p_application IS DISTINCT FROM current_setting(
           ''epm.application_id'',true) THEN
        RAISE EXCEPTION ''LAYOUT_REPLACEMENT_SCOPE_INVALID''
            USING ERRCODE=''42501'';
    END IF;
    SELECT r.target_generation_id,r.expected_coordinate_count
      INTO v_generation,v_expected
      FROM epm.layout_replacement_request r
     WHERE r.workspace_id=p_workspace AND r.application_id=p_application
       AND r.request_id=p_request;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT count(*) INTO v_count
      FROM epm.layout_replacement_staged_coordinate c
     WHERE c.workspace_id=p_workspace AND c.application_id=p_application
       AND c.generation_id=v_generation;
    IF v_count<>v_expected OR v_count>100000 THEN
        RAISE EXCEPTION ''LAYOUT_REPLACEMENT_STAGED_MAPPING_INVALID'';
    END IF;
    RETURN QUERY
    SELECT c.source_coordinate_id,c.target_members
      FROM epm.layout_replacement_staged_coordinate c
     WHERE c.workspace_id=p_workspace AND c.application_id=p_application
       AND c.generation_id=v_generation
     ORDER BY c.source_coordinate_id;
END ';

CREATE FUNCTION "epm"."layout_replacement_worker_recover"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
 UPDATE epm.layout_replacement_request SET status=''Accepted'',
  claim_generation=claim_generation+1,claimant=NULL,lease_until=NULL,
  updated_at=transaction_timestamp()
 WHERE status=''Staging'' AND lease_until<=clock_timestamp();
 GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed;
END ';

CREATE FUNCTION "epm"."planning_assignment_version_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
 IF TG_OP=''DELETE'' AND current_setting(''epm.projection_cleanup_reset_context'',true)=
    jsonb_build_array(OLD.workspace_id,pg_current_xact_id()::text,
                      pg_backend_pid())::text THEN RETURN OLD; END IF;
 RAISE EXCEPTION ''PLANNING_ASSIGNMENT_VERSION_IMMUTABLE'' USING ERRCODE=''23514'';
END';

CREATE FUNCTION "epm"."projection_cleanup_allowed"("w" "text", "a" "text", "target" bigint, "required_phase" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE m epm.projection_cleanup_manifest%ROWTYPE; current_generation bigint; capability jsonb;
BEGIN
    IF coalesce(current_setting(''epm.projection_cleanup_context'',true),'''')=''''
       AND coalesce(current_setting(''epm.projection_cleanup_reset_context'',true),'''')='''' THEN RETURN false; END IF;
    IF NOT pg_has_role(current_user,(SELECT relowner FROM pg_class
        WHERE oid=''epm.operation_receipt''::regclass),''USAGE'') THEN RETURN false; END IF;
    IF current_setting(''epm.projection_cleanup_reset_context'',true)=
        jsonb_build_array(w,pg_current_xact_id()::text,pg_backend_pid())::text
       AND EXISTS(SELECT 1 FROM epm.workspace WHERE workspace_id=w AND status=''Maintenance'') THEN RETURN true; END IF;
    IF coalesce(current_setting(''epm.projection_cleanup_context'',true),'''')='''' THEN RETURN false; END IF;
    capability:=current_setting(''epm.projection_cleanup_context'',true)::jsonb;
    SELECT * INTO m FROM epm.projection_cleanup_manifest x WHERE x.workspace_id=w AND x.application_id=a
        AND x.job_id=capability->>2 AND x.target_generation=target AND (required_phase IS NULL OR x.phase=required_phase)
        AND x.context_xid=pg_current_xact_id()::text AND x.context_pid=pg_backend_pid()
        AND current_setting(''epm.projection_cleanup_context'',true)=jsonb_build_array(
            w,a,x.job_id,target,x.context_claim,x.context_xid,x.context_pid)::text;
    IF NOT FOUND THEN RETURN false; END IF;
    SELECT active_projection_generation INTO current_generation FROM epm.application_state
        WHERE workspace_id=w AND application_id=a;
    IF current_generation IS NULL OR current_generation=target THEN RETURN false; END IF;
    IF NOT EXISTS(SELECT 1 FROM epm.job j WHERE j.workspace_id=w AND j.application_id=a
        AND j.job_id=m.job_id AND j.status=''running'' AND j.claim_generation=m.context_claim
        AND j.lease_until>clock_timestamp()) THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    RETURN true;
END ';

CREATE FUNCTION "epm"."projection_cleanup_target"("w" "text", "a" "text", "rid" "text", "kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE r epm.projection_recovery_manifest%ROWTYPE; j epm.job%ROWTYPE;
    s epm.application_state%ROWTYPE; target bigint;
BEGIN
    IF current_setting(''epm.workspace_id'',true) IS DISTINCT FROM w
       OR current_setting(''epm.application_id'',true) IS DISTINCT FROM a THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_SCOPE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF rid IS NULL OR rid!~''^[0-9a-f]{32}$'' OR kind IS NULL OR kind NOT IN (''abandoned'',''retired'') THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_TARGET_INVALID'' USING ERRCODE=''23514'';
    END IF;
    SELECT * INTO r FROM epm.projection_recovery_manifest WHERE workspace_id=w AND application_id=a AND job_id=rid;
    SELECT * INTO j FROM epm.job WHERE workspace_id=w AND application_id=a AND job_id=rid;
    SELECT * INTO s FROM epm.application_state WHERE workspace_id=w AND application_id=a;
    IF r.job_id IS NULL OR j.job_id IS NULL OR s.application_id IS NULL
       OR j.function_name<>''facts.projections.rebuild'' OR j.compiler_version<>''fact-projections-rebuild-v2'' THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_TARGET_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF kind=''retired'' THEN
        IF r.phase<>''published'' OR j.status<>''published'' OR NOT EXISTS(
            SELECT 1 FROM epm.operation_receipt o WHERE o.workspace_id=w AND o.application_id=a
            AND o.operation_id=rid AND o.sealed AND o.command_digest=j.program_digest
            AND o.actor_id=j.subject_id AND o.committed_revision=j.receipt_revision) THEN
            RAISE EXCEPTION ''PROJECTION_CLEANUP_TARGET_INVALID'' USING ERRCODE=''23514'';
        END IF;
        target:=r.original_generation;
    ELSE
        IF j.status NOT IN (''failed'',''cancelled'') OR r.phase=''published'' OR EXISTS(
            SELECT 1 FROM epm.operation_receipt o WHERE o.workspace_id=w AND o.application_id=a AND o.operation_id=rid) THEN
            RAISE EXCEPTION ''PROJECTION_CLEANUP_TARGET_INVALID'' USING ERRCODE=''23514'';
        END IF;
        target:=r.target_generation;
    END IF;
    IF target=s.active_projection_generation THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_TARGET_ACTIVE'' USING ERRCODE=''23514'';
    END IF;
    RETURN jsonb_build_object(''rebuildJobId'',rid,''generationKind'',kind,''targetGeneration'',target,
        ''recoveryProgramDigest'',j.program_digest,''schemaEpoch'',s.schema_epoch);
END ';

CREATE FUNCTION "epm"."projection_generations_cleanup_step"("w" "text", "a" "text", "jid" "text", "claimant_name" "text", "generation" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE s epm.application_state%ROWTYPE; j epm.job%ROWTYPE;
    m epm.projection_cleanup_manifest%ROWTYPE; p jsonb; resolved jsonb;
    physical text; ordering text; next_phase text; deleted bigint:=0; serialized_bytes bigint:=0;
    revision bigint; output jsonb;
BEGIN
    IF current_setting(''epm.workspace_id'',true) IS DISTINCT FROM w
       OR current_setting(''epm.application_id'',true) IS DISTINCT FROM a THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_SCOPE_INVALID'' USING ERRCODE=''23514'';
    END IF;
    PERFORM pg_advisory_xact_lock_shared(hashtextextended(''epm.security.workspace:''||w,0));
    SELECT * INTO s FROM epm.application_state WHERE workspace_id=w AND application_id=a FOR UPDATE;
    SELECT * INTO j FROM epm.job WHERE workspace_id=w AND application_id=a AND job_id=jid;
    IF s.application_id IS NULL OR j.job_id IS NULL OR j.function_name<>''facts.projections.cleanup''
       OR j.compiler_version<>''projection-generations-cleanup-v1''
       OR j.plan_digest<>''b264fe3557ae52e85b2ee89a757e153d926bd0721947e4727781233bf2019f29''
       OR j.resource_class<>''long'' THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF j.status<>''running'' OR j.claimant IS DISTINCT FROM claimant_name
       OR j.claim_generation IS DISTINCT FROM generation
       OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    p:=j.normalized_program;
    IF p->>''function'' IS DISTINCT FROM ''facts.projections.cleanup'' OR p->>''version'' IS DISTINCT FROM ''1''
       OR p-ARRAY[''version'',''function'',''reason'',''rebuildJobId'',''generationKind'',''targetGeneration'',''recoveryProgramDigest'',''schemaEpoch'']<>''{}''::jsonb
       OR jsonb_typeof(p->''reason'') IS DISTINCT FROM ''string''
       OR length(p->>''reason'') NOT BETWEEN 1 AND 500 OR (p->>''reason'')~''^[[:space:]]|[[:space:]]$''
       OR jsonb_typeof(p->''rebuildJobId'') IS DISTINCT FROM ''string'' OR (p->>''rebuildJobId'')!~''^[0-9a-f]{32}$''
       OR jsonb_typeof(p->''generationKind'') IS DISTINCT FROM ''string'' OR p->>''generationKind'' NOT IN (''abandoned'',''retired'')
       OR jsonb_typeof(p->''recoveryProgramDigest'') IS DISTINCT FROM ''string'' OR (p->>''recoveryProgramDigest'')!~''^[0-9a-f]{64}$''
       OR jsonb_typeof(p->''targetGeneration'') IS DISTINCT FROM ''number''
       OR jsonb_typeof(p->''schemaEpoch'') IS DISTINCT FROM ''number''
       OR (p->>''targetGeneration'')!~''^(0|[1-9][0-9]*)$''
       OR (p->>''schemaEpoch'')!~''^(0|[1-9][0-9]*)$'' THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF j.program_digest IS DISTINCT FROM encode(sha256(convert_to(
        ''{"function":"facts.projections.cleanup","generationKind":''||(p->''generationKind'')::text||
        '',"reason":''||(p->''reason'')::text||'',"rebuildJobId":''||(p->''rebuildJobId'')::text||
        '',"recoveryProgramDigest":''||(p->''recoveryProgramDigest'')::text||'',"schemaEpoch":''||(p->>''schemaEpoch'')||
        '',"targetGeneration":''||(p->>''targetGeneration'')||'',"version":1}'',''UTF8'')),''hex'') THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF s.commit_open OR s.schema_epoch<>(p->>''schemaEpoch'')::bigint THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_SCHEMA_CHANGED'' USING ERRCODE=''23514'';
    END IF;
    IF s.processing_mode<>''Active''
       OR NOT EXISTS(SELECT 1 FROM epm.workspace WHERE workspace_id=w AND status=''Active'')
       OR NOT EXISTS(SELECT 1 FROM epm.application WHERE workspace_id=w AND application_id=a AND status=''Active'') THEN
        RAISE EXCEPTION ''APPLICATION_NOT_WRITABLE'' USING ERRCODE=''23514'';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM epm.workspace_access_grant WHERE workspace_id=w AND issuer=j.issuer
          AND subject_id=j.subject_id AND role=''Administrator'')
       AND NOT EXISTS(SELECT 1 FROM epm.application_access_grant WHERE workspace_id=w AND application_id=a
          AND issuer=j.issuer AND subject_id=j.subject_id AND role=''Administrator'') THEN
        RAISE EXCEPTION ''APPLICATION_GRANT_REQUIRED'' USING ERRCODE=''23514'';
    END IF;
    resolved:=epm.projection_cleanup_target(w,a,p->>''rebuildJobId'',p->>''generationKind'');
    IF (resolved->>''targetGeneration'')::bigint<>(p->>''targetGeneration'')::bigint
       OR resolved->>''recoveryProgramDigest'' IS DISTINCT FROM p->>''recoveryProgramDigest'' THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_TARGET_INVALID'' USING ERRCODE=''23514'';
    END IF;
    SELECT * INTO m FROM epm.projection_cleanup_manifest WHERE workspace_id=w AND application_id=a AND job_id=jid FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO epm.projection_cleanup_manifest(workspace_id,application_id,job_id,rebuild_job_id,generation_kind,
            target_generation,schema_epoch,recovery_program_digest)
        VALUES(w,a,jid,p->>''rebuildJobId'',p->>''generationKind'',(p->>''targetGeneration'')::bigint,
            (p->>''schemaEpoch'')::bigint,p->>''recoveryProgramDigest'') RETURNING * INTO m;
    END IF;
    IF ROW(m.rebuild_job_id,m.generation_kind,m.target_generation,m.schema_epoch,m.recovery_program_digest)
        IS DISTINCT FROM ROW(p->>''rebuildJobId'',p->>''generationKind'',(p->>''targetGeneration'')::bigint,
            (p->>''schemaEpoch'')::bigint,p->>''recoveryProgramDigest'') THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_JOB_INVALID'' USING ERRCODE=''23514'';
    END IF;
    IF m.target_generation=s.active_projection_generation THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_TARGET_ACTIVE'' USING ERRCODE=''23514'';
    END IF;
    UPDATE epm.projection_cleanup_manifest SET context_xid=pg_current_xact_id()::text,
        context_pid=pg_backend_pid(),context_claim=generation WHERE workspace_id=w AND application_id=a AND job_id=jid;
    PERFORM set_config(''epm.projection_cleanup_context'',jsonb_build_array(w,a,jid,m.target_generation,
        generation,pg_current_xact_id()::text,pg_backend_pid())::text,true);
    IF m.phase<>''publish'' THEN
        physical:=CASE m.phase WHEN ''numeric'' THEN ''numeric_cell_projection'' WHEN ''text'' THEN ''text_cell_projection''
            WHEN ''detail'' THEN ''line_detail_projection'' WHEN ''generic'' THEN ''generic_fact_projection''
            WHEN ''members'' THEN ''coordinate_member_projection'' WHEN ''projection'' THEN ''coordinate_projection_state'' END;
        ordering:=CASE m.phase WHEN ''generic'' THEN ''table_id,series_key''
            WHEN ''members'' THEN ''coordinate_id,dimension_id'' ELSE ''coordinate_id'' END;
        next_phase:=CASE m.phase WHEN ''numeric'' THEN ''text'' WHEN ''text'' THEN ''detail'' WHEN ''detail'' THEN ''generic''
            WHEN ''generic'' THEN ''members'' WHEN ''members'' THEN ''projection'' WHEN ''projection'' THEN ''publish'' END;
        IF physical IS NULL THEN RAISE EXCEPTION ''PROJECTION_CLEANUP_JOB_INVALID'' USING ERRCODE=''23514''; END IF;
        \x2d- LIMIT is inside a materialized relation before the byte window. The
        \x2d- window/count never sees the entire retained generation.
        EXECUTE format(''WITH candidates AS MATERIALIZED (
            SELECT ctid AS tid,octet_length(to_jsonb(p)::text)::bigint AS row_bytes FROM epm.%I p
            WHERE workspace_id=$1 AND application_id=$2 AND projection_generation=$3
            ORDER BY %s LIMIT 128), budget AS MATERIALIZED (
            SELECT tid,row_bytes,row_number() OVER(ORDER BY tid) AS ordinal,
                sum(row_bytes) OVER(ORDER BY tid ROWS UNBOUNDED PRECEDING) AS bytes FROM candidates),
            picked AS MATERIALIZED (SELECT tid,row_bytes FROM budget WHERE bytes<=1048576 OR ordinal=1),
            removed AS (DELETE FROM epm.%I d USING picked p WHERE d.ctid=p.tid
                AND d.workspace_id=$1 AND d.application_id=$2 AND d.projection_generation=$3 RETURNING d.ctid)
            SELECT (SELECT count(*) FROM removed),(SELECT coalesce(sum(row_bytes),0) FROM picked)'',physical,ordering,physical)
            INTO deleted,serialized_bytes USING w,a,m.target_generation;
        SET CONSTRAINTS epm.generic_projection_complete IMMEDIATE;
        SET CONSTRAINTS epm.generic_projection_complete DEFERRED;
        m.counters:=m.counters||jsonb_build_object(m.phase,coalesce((m.counters->>m.phase)::bigint,0)+deleted);
        IF deleted=0 THEN
            m.certificates:=m.certificates||jsonb_build_object(m.phase,true);
            m.phase:=next_phase;
        END IF;
    END IF;
    m.quantum_count:=m.quantum_count+1;
    SELECT * INTO j FROM epm.job WHERE workspace_id=w AND application_id=a AND job_id=jid FOR UPDATE;
    IF j.status<>''running'' OR j.claimant IS DISTINCT FROM claimant_name
       OR j.claim_generation IS DISTINCT FROM generation
       OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    UPDATE epm.projection_cleanup_manifest SET phase=m.phase,counters=m.counters,certificates=m.certificates,
        quantum_count=m.quantum_count,updated_at=clock_timestamp() WHERE workspace_id=w AND application_id=a AND job_id=jid;
    IF m.phase=''publish'' AND physical IS NULL THEN
        IF m.certificates<>''{"numeric":true,"text":true,"detail":true,"generic":true,"members":true,"projection":true}''::jsonb THEN
            RAISE EXCEPTION ''PROJECTION_CLEANUP_JOB_INVALID'' USING ERRCODE=''23514'';
        END IF;
        revision:=s.commit_revision+1;
        output:=jsonb_build_object(''committedRevision'',revision,''rebuildJobId'',m.rebuild_job_id,
            ''generationKind'',m.generation_kind,''targetGeneration'',m.target_generation,''reason'',p->>''reason'',
            ''projections'',m.counters,''historyPreserved'',true,''activeGenerationRetained'',true);
        UPDATE epm.application_state SET commit_revision=revision WHERE workspace_id=w AND application_id=a;
        INSERT INTO epm.operation_receipt(workspace_id,application_id,operation_id,command_digest,actor_id,committed_revision,result)
            VALUES(w,a,jid,j.program_digest,j.subject_id,revision,output);
        UPDATE epm.projection_cleanup_manifest SET phase=''published'',context_xid=NULL,context_pid=NULL,context_claim=NULL
            WHERE workspace_id=w AND application_id=a AND job_id=jid;
        UPDATE epm.job SET status=''published'',receipt_revision=revision,result=output,error_code=NULL,
            claimant=NULL,lease_until=NULL,updated_at=clock_timestamp() WHERE workspace_id=w AND application_id=a AND job_id=jid;
    ELSE
        output:=jsonb_build_object(''status'',''ready'',''checkpoint'',true,''phase'',m.phase,''deletedRows'',deleted,
            ''serializedBytes'',serialized_bytes,''targetGeneration'',m.target_generation,''quantumCount'',m.quantum_count);
        UPDATE epm.projection_cleanup_manifest SET context_xid=NULL,context_pid=NULL,context_claim=NULL,
            last_checkpoint_claimant=claimant_name,last_checkpoint_generation=generation,last_checkpoint_digest=j.program_digest
            WHERE workspace_id=w AND application_id=a AND job_id=jid;
        UPDATE epm.job SET status=''ready'',claimant=NULL,lease_until=NULL,error_code=NULL,result=output,
            attempts=greatest(attempts-1,0),updated_at=clock_timestamp() WHERE workspace_id=w AND application_id=a AND job_id=jid;
    END IF;
    PERFORM set_config(''epm.projection_cleanup_context'','''',true);
    RETURN output;
END ';

CREATE FUNCTION "epm"."projection_inactive_delete_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE required_phase text;
BEGIN
    required_phase:=CASE TG_TABLE_NAME WHEN ''numeric_cell_projection'' THEN ''numeric''
        WHEN ''text_cell_projection'' THEN ''text'' WHEN ''line_detail_projection'' THEN ''detail''
        WHEN ''generic_fact_projection'' THEN ''generic'' WHEN ''coordinate_member_projection'' THEN ''members''
        ELSE ''projection'' END;
    IF EXISTS(SELECT 1 FROM projection_removed p LEFT JOIN epm.application_state s USING(workspace_id,application_id)
        WHERE CASE WHEN p.projection_generation IS DISTINCT FROM s.active_projection_generation THEN NOT
            epm.projection_cleanup_allowed(p.workspace_id,p.application_id,p.projection_generation,required_phase) ELSE false END) THEN
        RAISE EXCEPTION ''PROJECTION_CLEANUP_DELETE_FORBIDDEN'' USING ERRCODE=''23514'';
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."projection_inactive_write_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE required_phase text;
BEGIN
    required_phase:=CASE TG_TABLE_NAME WHEN ''numeric_cell_projection'' THEN ''numeric''
        WHEN ''text_cell_projection'' THEN ''text'' WHEN ''line_detail_projection'' THEN ''detail''
        WHEN ''generic_fact_projection'' THEN ''generic'' ELSE ''coordinates'' END;
    IF EXISTS(SELECT 1 FROM projection_written p LEFT JOIN epm.application_state s USING(workspace_id,application_id)
        WHERE CASE WHEN p.projection_generation IS DISTINCT FROM s.active_projection_generation THEN NOT
        epm.staged_projection_allowed(p.workspace_id,p.application_id,p.projection_generation,required_phase) ELSE false END) THEN
        RAISE EXCEPTION ''RECONSTRUCTION_INACTIVE_WRITE_FORBIDDEN'' USING ERRCODE=''23514'';
    END IF;
    IF TG_OP=''UPDATE'' THEN
        IF EXISTS(SELECT 1 FROM projection_prior p LEFT JOIN epm.application_state s USING(workspace_id,application_id)
            WHERE CASE WHEN p.projection_generation IS DISTINCT FROM s.active_projection_generation THEN NOT
            epm.staged_projection_allowed(p.workspace_id,p.application_id,p.projection_generation,required_phase) ELSE false END) THEN
            RAISE EXCEPTION ''RECONSTRUCTION_INACTIVE_WRITE_FORBIDDEN'' USING ERRCODE=''23514'';
        END IF;
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."projection_recovery_staged_allowed"("w" "text", "a" "text", "target" bigint, "allowed_phase" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'
DECLARE m epm.projection_recovery_manifest%ROWTYPE;
BEGIN
    IF coalesce(current_setting(''epm.staged_projection_context'',true),'''')='''' THEN RETURN false; END IF;
    IF NOT pg_has_role(current_user,(SELECT relowner FROM pg_class
        WHERE oid=''epm.operation_receipt''::regclass),''USAGE'') THEN RETURN false; END IF;
    SELECT m0.* INTO m FROM epm.projection_recovery_manifest m0
        WHERE m0.workspace_id=w AND m0.application_id=a AND m0.target_generation=target
        AND m0.target_generation<>m0.original_generation
        AND (allowed_phase IS NULL OR m0.phase=allowed_phase)
        AND m0.context_xid=pg_current_xact_id()::text AND m0.context_pid=pg_backend_pid()
        AND current_setting(''epm.staged_projection_context'',true)=jsonb_build_array(
            w,a,m0.job_id,target,m0.context_claim,m0.context_xid,m0.context_pid)::text;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT EXISTS(SELECT 1 FROM epm.job j WHERE j.workspace_id=w AND j.application_id=a
        AND j.job_id=m.job_id AND j.status=''running'' AND j.claim_generation=m.context_claim
        AND j.lease_until>clock_timestamp()) THEN
        RAISE EXCEPTION ''STALE_WORKER_FENCE'' USING ERRCODE=''23514'';
    END IF;
    RETURN true;
END ';

CREATE FUNCTION "epm"."python_build_worker_settle"("p_workspace" "text", "p_application" "text", "p_build" "text", "p_generation" bigint, "p_claimant" "text", "p_error" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
  IF p_error NOT IN (''PYTHON_BUILD_AUTHORIZATION_REVOKED'',
                     ''PYTHON_BUILD_CAPABILITY_UNAVAILABLE'',
                     ''PYTHON_SANDBOX_RUNTIME_UNAVAILABLE'',
                     ''PYTHON_BUILD_WORKER_FAILED'') THEN
    RAISE EXCEPTION ''PYTHON_BUILD_WORKER_SETTLEMENT_INVALID'' USING ERRCODE=''22023'';
  END IF;
  UPDATE epm.python_program_build SET status=''failed'',error_code=p_error,
    claimant=NULL,lease_until=NULL,updated_at=transaction_timestamp()
  WHERE workspace_id=p_workspace AND application_id=p_application
    AND build_id=p_build AND status IN (''running'',''cancel_requested'')
    AND claim_generation=p_generation AND claimant=p_claimant
    AND lease_until>clock_timestamp();
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END ';

CREATE FUNCTION "epm"."python_occurrence_worker_claim"("p_claimant" "text", "p_lease" integer, "p_global" integer, "p_workspace" integer, "p_application" integer) RETURNS TABLE("workspace_id" "text", "application_id" "text", "occurrence_id" "text", "status" "text", "claim_generation" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE c record;BEGIN
 IF p_claimant IS NULL OR length(p_claimant) NOT BETWEEN 1 AND 200 OR p_lease NOT BETWEEN 5 AND 300
 OR p_application NOT BETWEEN 1 AND p_workspace OR p_workspace NOT BETWEEN 1 AND p_global
 THEN RAISE EXCEPTION ''PYTHON_OCCURRENCE_CLAIM_INVALID'' USING ERRCODE=''22023'';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(''epm.python.occurrence.dispatch'',0));
 IF (SELECT count(*) FROM epm.python_program_occurrence WHERE claimant IS NOT NULL AND lease_until>clock_timestamp())>=p_global THEN RETURN;END IF;
 SELECT o.* INTO c FROM epm.python_program_occurrence o LEFT JOIN epm.worker_workspace_dispatch d ON d.workspace_id=o.workspace_id
 WHERE o.status IN (''ready'',''running'',''building'',''running_program'',''cancel_requested'')
 AND (o.lease_until IS NULL OR o.lease_until<=clock_timestamp())
 AND (SELECT count(*) FROM epm.python_program_occurrence x WHERE x.workspace_id=o.workspace_id AND x.claimant IS NOT NULL AND x.lease_until>clock_timestamp())<p_workspace
 AND (SELECT count(*) FROM epm.python_program_occurrence x WHERE x.workspace_id=o.workspace_id AND x.application_id=o.application_id AND x.claimant IS NOT NULL AND x.lease_until>clock_timestamp())<p_application
 ORDER BY d.last_claim_sequence NULLS FIRST,o.due_at,o.occurrence_id FOR UPDATE OF o SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN;END IF;
 UPDATE epm.python_program_occurrence target SET status=CASE WHEN target.status=''ready'' THEN ''running'' ELSE target.status END,
  claim_generation=target.claim_generation+1,claimant=p_claimant,
  lease_until=clock_timestamp()+make_interval(secs=>p_lease),updated_at=transaction_timestamp()
 WHERE target.workspace_id=c.workspace_id AND target.application_id=c.application_id AND target.occurrence_id=c.occurrence_id;
 RETURN QUERY SELECT c.workspace_id,c.application_id,c.occurrence_id,
  CASE WHEN c.status=''ready'' THEN ''running'' ELSE c.status END,c.claim_generation+1;
END ';

CREATE FUNCTION "epm"."python_workflow_worker_release"("p_workspace" "text", "p_application" "text", "p_workflow" "text", "p_generation" bigint, "p_claimant" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
  UPDATE epm.python_program_workflow SET claimant=NULL,lease_until=NULL,
    worker_failures=0,worker_error_code=NULL,updated_at=transaction_timestamp()
  WHERE workspace_id=p_workspace AND application_id=p_application
    AND workflow_id=p_workflow AND claim_generation=p_generation
    AND claimant=p_claimant AND lease_until>clock_timestamp();
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END ';

CREATE FUNCTION "epm"."python_workflow_worker_renew"("p_workspace" "text", "p_application" "text", "p_workflow" "text", "p_generation" bigint, "p_claimant" "text", "p_lease_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
  IF p_lease_seconds NOT BETWEEN 30 AND 300 THEN
    RAISE EXCEPTION ''PYTHON_WORKFLOW_WORKER_RENEW_INVALID'' USING ERRCODE=''22023'';
  END IF;
  UPDATE epm.python_program_workflow SET
    lease_until=clock_timestamp()+make_interval(secs=>p_lease_seconds),
    updated_at=transaction_timestamp()
  WHERE workspace_id=p_workspace AND application_id=p_application
    AND workflow_id=p_workflow AND claim_generation=p_generation
    AND claimant=p_claimant AND lease_until>clock_timestamp()
    AND status IN (''accepted'',''running'',''cancel_requested'');
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END ';

CREATE FUNCTION "epm"."python_workflow_worker_settle"("p_workspace" "text", "p_application" "text", "p_workflow" "text", "p_generation" bigint, "p_claimant" "text", "p_error" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE changed integer;
BEGIN
  IF p_error NOT IN (''PYTHON_WORKFLOW_AUTHORIZATION_REVOKED'',
                     ''PYTHON_WORKFLOW_STALE_CONTEXT'') THEN
    RAISE EXCEPTION ''PYTHON_WORKFLOW_WORKER_SETTLEMENT_INVALID'' USING ERRCODE=''22023'';
  END IF;
  UPDATE epm.python_program_workflow SET
    status=CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(
      COALESCE(result->''checkpoints'',''[]''::jsonb)) c WHERE (c->>''committed'')::boolean)
      THEN ''partially_published'' ELSE ''failed'' END,
    result=jsonb_set(COALESCE(result,''{}''::jsonb),''{errorCode}'',to_jsonb(p_error)),
    claimant=NULL,lease_until=NULL,updated_at=transaction_timestamp()
  WHERE workspace_id=p_workspace AND application_id=p_application
    AND workflow_id=p_workflow AND claim_generation=p_generation
    AND claimant=p_claimant AND lease_until>clock_timestamp()
    AND status IN (''accepted'',''running'',''cancel_requested'');
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END ';

CREATE FUNCTION "epm"."raw_operation_membership_exists"("w" "text", "a" "text", "op" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm'
    SET "enable_seqscan" TO 'off'
    AS E'
BEGIN
    IF current_setting(''epm.workspace_id'',true) IS DISTINCT FROM w
       OR current_setting(''epm.application_id'',true) IS DISTINCT FROM a THEN
        RAISE EXCEPTION ''FACT_PUBLICATION_SCOPE_CHANGED'' USING ERRCODE=''23514'';
    END IF;
    RETURN EXISTS(SELECT 1 FROM epm.raw_operation_membership
        WHERE workspace_id=w AND application_id=a AND operation_id=op);
END ';

CREATE FUNCTION "epm"."raw_operation_membership_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'epm', 'pg_temp'
    AS E'
BEGIN
    IF TG_OP<>''INSERT'' OR TG_TABLE_SCHEMA<>''epm''
       OR TG_TABLE_NAME NOT IN (''numeric_fact_event'',''text_fact_event'',''line_detail_event'') THEN
        RAISE EXCEPTION ''RAW_OPERATION_MEMBERSHIP_TRIGGER_INVALID'' USING ERRCODE=''23514'';
    END IF;
    INSERT INTO epm.raw_operation_membership(workspace_id,application_id,operation_id)
        SELECT DISTINCT workspace_id,application_id,operation_id FROM raw_operation_inserted
        ON CONFLICT(workspace_id,application_id,operation_id) DO NOTHING;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."reject_sealed_acquisition_line"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE v_status text;
BEGIN
    SELECT status INTO v_status FROM epm.acquisition_journal
        WHERE workspace_id=NEW.workspace_id AND application_id=NEW.application_id
        AND journal_id=NEW.journal_id;
    IF v_status IS DISTINCT FROM ''Building'' THEN
        RAISE EXCEPTION ''ACQUISITION_JOURNAL_IMMUTABLE'' USING ERRCODE=''23514'';
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."round_half_even"("value" numeric, "places" integer) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE scale numeric;
DECLARE shifted numeric;
DECLARE base numeric;
DECLARE remainder numeric;
BEGIN
    IF places < 0 OR places > 12 THEN
        RAISE EXCEPTION ''ROUNDING_SCALE_UNSUPPORTED'';
    END IF;
    scale := power(10::numeric, places);
    shifted := abs(value) * scale;
    base := trunc(shifted);
    remainder := shifted - base;
    IF remainder > 0.5 OR (remainder = 0.5 AND mod(base,2) <> 0) THEN
        base := base + 1;
    END IF;
    RETURN sign(value) * base / scale;
END ';

CREATE FUNCTION "epm"."seal_acquisition_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
    IF OLD.status<>''Building'' OR NEW.status<>''Posted'' OR
       (to_jsonb(NEW)-''status'') IS DISTINCT FROM (to_jsonb(OLD)-''status'') THEN
        RAISE EXCEPTION ''ACQUISITION_JOURNAL_IMMUTABLE'' USING ERRCODE=''23514'';
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."settle_workspace_reset_batches"("p_workspace_id" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE
    v_status text;
    v_count bigint;
BEGIN
    IF p_workspace_id IS NULL OR p_workspace_id = '''' OR
       p_workspace_id <> current_setting(''epm.workspace_id'', true) THEN
        RAISE EXCEPTION ''RESET_SCOPE_INVALID'';
    END IF;
    IF current_setting(''transaction_isolation'') <> ''read committed'' THEN
        RAISE EXCEPTION ''RESET_REQUIRES_READ_COMMITTED'';
    END IF;
    PERFORM pg_advisory_xact_lock(
        hashtextextended(''epm.security.workspace:'' || p_workspace_id,0));
    SELECT status INTO v_status FROM epm.workspace
        WHERE workspace_id=p_workspace_id;
    IF v_status IS DISTINCT FROM ''Maintenance'' THEN
        RAISE EXCEPTION ''WORKSPACE_NOT_IN_MAINTENANCE'';
    END IF;
    IF (SELECT count(*) FROM epm.source_batch
        WHERE workspace_id=p_workspace_id AND status IN (''staging'',''ready''))
        > 1000 THEN
        RAISE EXCEPTION ''RESET_ACTIVE_TARGETS_EXCEED_LIMIT'';
    END IF;
    IF EXISTS (SELECT 1 FROM epm.source_batch b
        JOIN epm.operation_receipt r
          ON r.workspace_id=b.workspace_id
         AND r.application_id=b.application_id
         AND r.operation_id=b.batch_id
        WHERE b.workspace_id=p_workspace_id
          AND b.status IN (''staging'',''ready'')) THEN
        RAISE EXCEPTION ''SOURCE_BATCH_RECEIPT_REQUIRES_INSPECTION'';
    END IF;

    UPDATE epm.source_batch SET status=''failed'',
        result=jsonb_build_object(''errorCode'',''WORKSPACE_RESET_SETTLEMENT''),
        updated_at=transaction_timestamp()
        WHERE workspace_id=p_workspace_id AND status IN (''staging'',''ready'');
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END ';

CREATE FUNCTION "epm"."transfer_cleanup_certificate_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
 IF TG_OP=''DELETE'' AND current_setting(''epm.projection_cleanup_reset_context'',true)=
    jsonb_build_array(OLD.workspace_id,pg_current_xact_id()::text,
                      pg_backend_pid())::text THEN
  RETURN OLD;
 END IF;
 RAISE EXCEPTION ''TRANSFER_CLEANUP_CERTIFICATE_IMMUTABLE'' USING ERRCODE=''23514'';
END';

CREATE FUNCTION "epm"."validate_acquisition_journal_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
DECLARE v_count bigint; v_sum numeric; v_original text; v_header epm.acquisition_journal%ROWTYPE;
BEGIN
    SELECT * INTO v_header FROM epm.acquisition_journal
        WHERE workspace_id=NEW.workspace_id AND application_id=NEW.application_id
        AND journal_id=NEW.journal_id;
    IF v_header.status IS DISTINCT FROM ''Posted'' THEN
        RAISE EXCEPTION ''ACQUISITION_JOURNAL_NOT_SEALED'' USING ERRCODE=''23514'';
    END IF;
    SELECT count(*),sum(signed_amount) INTO v_count,v_sum
        FROM epm.acquisition_journal_line WHERE workspace_id=NEW.workspace_id
        AND application_id=NEW.application_id AND journal_id=NEW.journal_id;
    IF v_count NOT BETWEEN 2 AND 5 OR v_sum IS DISTINCT FROM 0::numeric THEN
        RAISE EXCEPTION ''ACQUISITION_JOURNAL_NOT_BALANCED'' USING ERRCODE=''23514'';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM epm.policy_activation_event e
        WHERE e.workspace_id=NEW.workspace_id AND e.application_id=NEW.application_id
        AND e.event_id=v_header.activation_id AND e.action=''Activate'') THEN
        RAISE EXCEPTION ''ACQUISITION_ACTIVATION_EVENT_REQUIRED'' USING ERRCODE=''23514'';
    END IF;
    v_original := v_header.reversal_of;
    IF v_original IS NOT NULL THEN
        IF NOT EXISTS(SELECT 1 FROM epm.acquisition_journal j
            WHERE j.workspace_id=NEW.workspace_id AND j.application_id=NEW.application_id
            AND j.journal_id=v_original AND j.reversal_of IS NULL
            AND j.acquisition_key=v_header.acquisition_key
            AND j.activation_id=v_header.activation_id
            AND j.currency_dimension_id=v_header.currency_dimension_id
            AND j.currency_member_id=v_header.currency_member_id) OR EXISTS(
                SELECT 1 FROM (SELECT coordinate_id,line_role,signed_amount
                    FROM epm.acquisition_journal_line WHERE workspace_id=NEW.workspace_id
                    AND application_id=NEW.application_id AND journal_id=v_original) original
                FULL JOIN (SELECT coordinate_id,line_role,signed_amount
                    FROM epm.acquisition_journal_line WHERE workspace_id=NEW.workspace_id
                    AND application_id=NEW.application_id AND journal_id=NEW.journal_id) reversal
                USING(coordinate_id,line_role)
                WHERE original.coordinate_id IS NULL OR reversal.coordinate_id IS NULL
                OR original.signed_amount<>-reversal.signed_amount) THEN
            RAISE EXCEPTION ''ACQUISITION_REVERSAL_MISMATCH'' USING ERRCODE=''23514'';
        END IF;
    END IF;
    RETURN NULL;
END ';

CREATE FUNCTION "epm"."validate_financial_period_close_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
    IF TG_OP=''INSERT'' THEN
        IF NEW.status<>''Closed'' OR NEW.version<>1
           OR NEW.reopened_revision IS NOT NULL THEN
            RAISE EXCEPTION ''FINANCIAL_CLOSE_INITIAL_STATE_INVALID'';
        END IF;
    ELSIF OLD.status<>''Closed'' OR NEW.status<>''Reopened''
          OR NEW.version<>2 OR NEW.reopened_revision IS NULL
          OR NEW.reopened_revision<=OLD.closed_revision THEN
        RAISE EXCEPTION ''FINANCIAL_CLOSE_TRANSITION_INVALID'';
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."validate_planning_assigned_chain"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'epm'
    AS E'DECLARE a record;cnt integer;maxord integer;BEGIN
 SELECT * INTO a FROM epm.planning_assigned_submission WHERE workspace_id=NEW.workspace_id AND application_id=NEW.application_id AND lock_id=NEW.lock_id;
 IF a IS NULL THEN RETURN NEW;END IF;
 SELECT count(*),coalesce(max(reviewer_ordinal),0) INTO cnt,maxord FROM epm.planning_assigned_reviewer WHERE workspace_id=NEW.workspace_id AND application_id=NEW.application_id AND lock_id=NEW.lock_id;
 IF cnt<>a.step_count OR maxord<>a.step_count OR a.current_step>cnt THEN RAISE EXCEPTION ''PLANNING_ASSIGNED_CHAIN_INVALID'';END IF;
 RETURN NEW;END';

CREATE FUNCTION "epm"."validate_planning_lock_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
    IF TG_OP=''INSERT'' THEN
        IF NEW.status<>''Locked'' OR NEW.version<>1
           OR NEW.reopened_revision IS NOT NULL THEN
            RAISE EXCEPTION ''PLANNING_LOCK_INITIAL_STATE_INVALID'';
        END IF;
    ELSIF OLD.status<>''Locked'' OR NEW.status<>''Open''
          OR NEW.version<>OLD.version+1
          OR NEW.reopened_revision IS NULL
          OR NEW.reopened_revision<=OLD.locked_revision THEN
        RAISE EXCEPTION ''PLANNING_LOCK_TRANSITION_INVALID'';
    END IF;
    RETURN NEW;
END ';

CREATE FUNCTION "epm"."validate_planning_submission_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS E'
BEGIN
    IF TG_OP=''INSERT'' THEN
        IF NEW.status<>''Submitted'' OR NEW.version<>1 THEN
            RAISE EXCEPTION ''PLANNING_SUBMISSION_INITIAL_STATE_INVALID'';
        END IF;
    ELSIF NOT (
        (OLD.status=''Submitted'' AND NEW.status=''Approved''
            AND NEW.version=2 AND NEW.approved_revision IS NOT NULL)
        OR (OLD.status=''Submitted'' AND NEW.status=''Reopened''
            AND NEW.version=2 AND NEW.reopened_revision IS NOT NULL)
        OR (OLD.status=''Approved'' AND NEW.status=''Reopened''
            AND NEW.version=3 AND NEW.reopened_revision IS NOT NULL)) THEN
        RAISE EXCEPTION ''PLANNING_SUBMISSION_TRANSITION_INVALID'';
    END IF;
    RETURN NEW;
END ';

